insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-rhythm-rainbow-planner', 'Weekly Rhythm Rainbow Planner', 'worksheet'::resource_kind, 'A seven-day planner that sorts the week into rest, effort, connection and fun blocks.', 'Use it to help a client see how their week is balanced and where one area is missing.', array['Adults', 'Teens']::text[], 'One week', 'Have the client color a block for each part of the day, then look at the page together. Notice which color dominates and which is missing, and let them decide what to move. It works best when the client fills it from real days, not ideal ones. Offer it as a picture of the week, not a grade.', '[{"id": "f0", "type": "textarea", "label": "Which color shows up most on my week?"}, {"id": "f1", "type": "textarea", "label": "Which color is almost missing?"}, {"id": "f2", "type": "textarea", "label": "One block I could move or add"}, {"id": "f3", "type": "textarea", "label": "What might get in the way of that change?"}, {"id": "f4", "type": "textarea", "label": "How I will check in on it next week"}]'::jsonb, array['planning', 'routines', 'self-monitoring']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('unsent-letter-page', 'Unsent Letter Page', 'worksheet'::resource_kind, 'A guided page for writing a letter the client will not send, shaped by three short prompts.', 'Use it to give a client a private place to put words they have not been able to say aloud.', array['Adults', 'Teens']::text[], '20 minutes', 'Decide with the client before writing whether the letter stays in session, goes home, or is set aside. Remind them it is not to be sent. Keep to the prompts so it stays contained, and leave time at the end to settle with a grounding step. What they do with the letter is theirs.', '[{"id": "f0", "type": "textarea", "label": "Who is this letter to?"}, {"id": "f1", "type": "textarea", "label": "What I wish they knew"}, {"id": "f2", "type": "textarea", "label": "What I want to say that I have held back"}, {"id": "f3", "type": "textarea", "label": "What I need from myself after writing this"}, {"id": "f4", "type": "textarea", "label": "Where this letter will go when I am done"}]'::jsonb, array['expression', 'support', 'writing']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('choice-weighing-grid-with-a-values-column', 'Choice Weighing Grid With a Values Column', 'worksheet'::resource_kind, 'A grid that adds a values column to the usual pros and cons for a choice the client is weighing.', 'Use it to help a client weigh a decision by what matters to them, not only by what is easy.', array['Adults', 'Teens']::text[], '30 minutes', 'Ask for the decision in one sentence before anything else. Fill both columns for each option, then add the value each point touches. Clients often find the grid does not give an answer but shows what they are protecting. Leave the choice with them and plan one small next step.', '[{"id": "f0", "type": "textarea", "label": "The decision, in one sentence"}, {"id": "f1", "type": "textarea", "label": "Good things about option one"}, {"id": "f2", "type": "textarea", "label": "Hard things about option one"}, {"id": "f3", "type": "textarea", "label": "Good things about option two"}, {"id": "f4", "type": "textarea", "label": "Hard things about option two"}, {"id": "f5", "type": "textarea", "label": "The value each point touches"}, {"id": "f6", "type": "textarea", "label": "My smallest next step"}]'::jsonb, array['decisions', 'values', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('energy-budget-spoons-sheet', 'Energy Budget Spoons Sheet', 'worksheet'::resource_kind, 'A page where a client spends a set number of energy tokens across a day and notes what was left.', 'Use it to help a client notice what their day costs them and what refills them.', array['Adults', 'Teens']::text[], 'Three to five days', 'Agree on a number of tokens together, such as ten, and let the client name what each task costs. Review the leftovers, not the totals. Clients who tend to overspend often learn the most from the refill column. Treat the numbers as the client''s own estimates.', '[{"id": "f0", "type": "textarea", "label": "Tasks today and what I spent on each"}, {"id": "f1", "type": "textarea", "label": "What I had left at night"}, {"id": "f2", "type": "textarea", "label": "What refilled me"}, {"id": "f3", "type": "textarea", "label": "Where I overspent"}, {"id": "f4", "type": "textarea", "label": "What I would trade out tomorrow"}]'::jsonb, array['routines', 'self-monitoring', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('support-rings-placement-map', 'Support Rings Placement Map', 'worksheet'::resource_kind, 'A set of concentric circles where a client places the people and places that support them.', 'Use it to help a client see who is in their support network and where a gap might be.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw three rings and let the client place names, pets, groups and places by how close they feel. Do not move anything for them. Look together at the empty spots and ask what kind of support is missing. It is a picture of today, and it may change.', '[{"id": "f0", "type": "textarea", "label": "People I place in the closest ring"}, {"id": "f1", "type": "textarea", "label": "People and places in the middle ring"}, {"id": "f2", "type": "textarea", "label": "Who sits further out and why"}, {"id": "f3", "type": "textarea", "label": "What kind of support feels missing"}, {"id": "f4", "type": "textarea", "label": "One person I could reach out to this week"}]'::jsonb, array['support', 'connection', 'strengths']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('hot-thought-evidence-scale', 'Hot Thought Evidence Scale', 'cbt'::resource_kind, 'A worksheet that rates how strongly a client believes a thought before and after weighing evidence both ways.', 'Use it to help a client see how belief in a thought moves once they look at both sides.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick one thought from a thought record and have the client rate belief from 0 to 100 first. List the facts that fit and the facts that do not, then rate again. A small shift is fine; no particular number is the goal. Ask what they notice about how the thought felt before and after.', '[{"id": "f0", "type": "textarea", "label": "The thought and how strongly I believe it (0 to 100)"}, {"id": "f1", "type": "textarea", "label": "Facts that fit the thought"}, {"id": "f2", "type": "textarea", "label": "Facts that do not fit it"}, {"id": "f3", "type": "textarea", "label": "How strongly I believe it now (0 to 100)"}, {"id": "f4", "type": "textarea", "label": "What I notice about the change"}]'::jsonb, array['core CBT', 'thinking traps', 'thought record']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('worry-time-container-plan', 'Worry Time Container Plan', 'cbt'::resource_kind, 'A plan for setting aside one short window each day for worries and parking the rest.', 'Use it to give a client a way to postpone worry and look at it at a chosen time.', array['Adults', 'Teens']::text[], 'Two weeks', 'Help the client choose a time, a place and a length, such as 15 minutes mid-afternoon. Between sessions they jot a worry on a list and return to the task. During the window they sort each item into something to act on or something to let be. Expect to adjust the window after a week.', '[{"id": "f0", "type": "textarea", "label": "My worry window: time, place and length"}, {"id": "f1", "type": "textarea", "label": "A worry I parked today"}, {"id": "f2", "type": "textarea", "label": "What I did instead"}, {"id": "f3", "type": "textarea", "label": "In the window, what I can act on"}, {"id": "f4", "type": "textarea", "label": "What I will let be for now"}]'::jsonb, array['core CBT', 'worry', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('other-explanations-spoke-wheel', 'Other Explanations Spoke Wheel', 'cbt'::resource_kind, 'A wheel where a client lists other possible reasons for an event that first looked like proof of something bad.', 'Use it to help a client generate other explanations before settling on the first one.', array['Adults', 'Teens']::text[], '20 minutes', 'Draw a circle with the event in the center and spokes around it. The client fills spokes with explanations, including silly ones, because quantity loosens the grip of the first guess. Then ask which are most likely and what could be checked. The first explanation may still be true, and that is allowed.', '[{"id": "f0", "type": "textarea", "label": "The event, in plain words"}, {"id": "f1", "type": "textarea", "label": "My first explanation"}, {"id": "f2", "type": "textarea", "label": "Three other possible explanations"}, {"id": "f3", "type": "textarea", "label": "One that is a little funny or unlikely"}, {"id": "f4", "type": "textarea", "label": "How I could find out which fits best"}]'::jsonb, array['core CBT', 'thinking traps', 'behavioral experiment']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-planner-card', 'Behavioral Experiment Planner Card', 'cbt'::resource_kind, 'A one-page card to plan, run and review a small experiment that tests a prediction.', 'Use it to help a client test a prediction in real life and record what actually happened.', array['Adults', 'Teens']::text[], 'One week', 'Make the prediction specific and checkable, such as what will be said or done, and rate belief beforehand. Keep the experiment small enough to do within the week. Afterward compare what happened with what was predicted, without judgment about the client for being wrong or right. Plan the next one together.', '[{"id": "f0", "type": "textarea", "label": "My prediction, as specific as I can make it"}, {"id": "f1", "type": "textarea", "label": "How much I believe it (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "The experiment I will run, and when"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}, {"id": "f5", "type": "textarea", "label": "What I might test next"}]'::jsonb, array['core CBT', 'behavioral experiment', 'exposure']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('core-belief-downward-arrow-page', 'Core Belief Downward Arrow Page', 'cbt'::resource_kind, 'A page that follows a thought down with the question "and if that were true, what would it mean?".', 'Use it to help a client trace a surface thought toward the deeper belief underneath it.', array['Adults']::text[], 'Full session', 'Go slowly and keep the client in charge of how far down to go. Stop if they become flooded, and close by grounding and naming a kinder alternative at the bottom. This is best done in session. Treat the belief as an idea the client holds, not a fact about them.', '[{"id": "f0", "type": "textarea", "label": "The thought I started with"}, {"id": "f1", "type": "textarea", "label": "If that were true, it would mean..."}, {"id": "f2", "type": "textarea", "label": "And if that were true, it would mean..."}, {"id": "f3", "type": "textarea", "label": "The belief I land on"}, {"id": "f4", "type": "textarea", "label": "Where I think that belief came from"}, {"id": "f5", "type": "textarea", "label": "A kinder statement that I could try"}]'::jsonb, array['core CBT', 'core beliefs', 'self-talk']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('leaves-on-the-stream-daily-practice-log', 'Leaves on the Stream Daily Practice Log', 'act'::resource_kind, 'A log for a defusion practice where thoughts are placed on leaves floating down a stream.', 'Use it to help a client practice letting thoughts pass without following or fighting them.', array['Adults', 'Teens']::text[], 'Five minutes daily for a week', 'Guide the practice once in session so the client knows the image. At home they note when they tried it and what thoughts floated by. Common snags are getting caught in a thought and judging the practice as failing. Noticing that they got caught and returning is the practice.', '[{"id": "f0", "type": "textarea", "label": "When and where I practiced"}, {"id": "f1", "type": "textarea", "label": "Thoughts that floated by"}, {"id": "f2", "type": "textarea", "label": "A moment I got caught on a leaf"}, {"id": "f3", "type": "textarea", "label": "How I came back"}, {"id": "f4", "type": "textarea", "label": "How my body felt afterward"}]'::jsonb, array['core ACT', 'defusion', 'mindfulness']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('values-compass-quarter-check', 'Values Compass Quarter Check', 'act'::resource_kind, 'A compass-style page for rating how closely the client is living by four chosen values.', 'Use it to help a client check how their actions line up with the values they named.', array['Adults', 'Teens']::text[], '25 minutes', 'Have the client name four values in their own words, then rate each for how much their recent actions have matched it. Ask about the gap, not the score. Pick one value for a small action in the next week. Avoid shoulds; the client chooses the direction.', '[{"id": "f0", "type": "textarea", "label": "Four values in my own words"}, {"id": "f1", "type": "textarea", "label": "How closely my days match each (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "The value with the biggest gap"}, {"id": "f3", "type": "textarea", "label": "One small action that fits it"}, {"id": "f4", "type": "textarea", "label": "What may show up when I try"}, {"id": "f5", "type": "textarea", "label": "How I will make room for that"}]'::jsonb, array['core ACT', 'values', 'committed action']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('willingness-dial-worksheet', 'Willingness Dial Worksheet', 'act'::resource_kind, 'A dial the client turns to show how willing they are to feel something uncomfortable for a valued step.', 'Use it to help a client notice and adjust their willingness to carry discomfort toward something they care about.', array['Adults', 'Teens']::text[], '20 minutes', 'Name one valued step and the discomfort that comes with it, then have the client set the dial from 0 to 10. Ask what would move it up a notch, or what a smaller version of the step might be. Do not push the dial higher than the client wants. Willingness is a choice they make again each time.', '[{"id": "f0", "type": "textarea", "label": "The step I care about taking"}, {"id": "f1", "type": "textarea", "label": "The discomfort that comes with it"}, {"id": "f2", "type": "textarea", "label": "My willingness today (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "What would move it up one notch"}, {"id": "f4", "type": "textarea", "label": "A smaller version of the step"}, {"id": "f5", "type": "textarea", "label": "What I will do this week"}]'::jsonb, array['core ACT', 'willingness', 'values']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('self-as-context-observer-page', 'Self as Context Observer Page', 'act'::resource_kind, 'A page that helps a client practice stepping back and noticing the one who notices their experience.', 'Use it to help a client get a bit of distance from thoughts and feelings by noticing the observing self.', array['Adults']::text[], '20 minutes', 'Lead a short observer exercise in session, such as noticing thoughts, feelings and sensations as passing contents. Then use the page to capture what the client saw. Some clients find the idea abstract, so offer the image of the sky and the weather. Keep it curious and light.', '[{"id": "f0", "type": "textarea", "label": "What I noticed in my body"}, {"id": "f1", "type": "textarea", "label": "What I noticed in my thoughts"}, {"id": "f2", "type": "textarea", "label": "What I noticed in my feelings"}, {"id": "f3", "type": "textarea", "label": "Who or what was noticing all of that"}, {"id": "f4", "type": "textarea", "label": "What stayed the same while the rest changed"}]'::jsonb, array['core ACT', 'mindfulness', 'self as context']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('crossroads-choice-point-sketch', 'Crossroads Choice Point Sketch', 'act'::resource_kind, 'A map that marks the moment of a hard feeling and the two directions a client can take from it.', 'Use it to help a client spot a choice point and name moves toward and away from what matters.', array['Adults', 'Teens']::text[], '25 minutes', 'Draw a crossroads with the hook in the center. The client lists the thoughts and feelings that show up, then moves that take them away and moves that take them toward. Practice on a recent moment, not a hypothetical one. It helps to leave the map with the client for use between sessions.', '[{"id": "f0", "type": "textarea", "label": "The moment that started it"}, {"id": "f1", "type": "textarea", "label": "Thoughts and feelings that showed up"}, {"id": "f2", "type": "textarea", "label": "Moves that take me away from what matters"}, {"id": "f3", "type": "textarea", "label": "Moves that take me toward what matters"}, {"id": "f4", "type": "textarea", "label": "The direction I chose"}, {"id": "f5", "type": "textarea", "label": "What I want to try next time"}]'::jsonb, array['core ACT', 'choice point', 'committed action']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('emotion-reason-and-wise-mind-pause-card', 'Emotion, Reason and Wise Mind Pause Card', 'dbt'::resource_kind, 'A short card for noticing emotion mind, reasonable mind and wise mind in a moment of difficulty.', 'Use it to help a client practice finding a wise mind response between the two extremes.', array['Adults', 'Teens']::text[], '15 minutes', 'Walk through a recent moment, asking where each mind was speaking. The client then writes what wise mind might say. Some clients struggle to find it at first, so offer a breath or a hand on the belly. It can be used in session as a pause before a hard conversation.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What emotion mind was saying"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind was saying"}, {"id": "f3", "type": "textarea", "label": "What wise mind might say"}, {"id": "f4", "type": "textarea", "label": "How I could act from that"}]'::jsonb, array['core DBT', 'mindfulness', 'emotion regulation']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('improve-letters-moment-menu', 'IMPROVE Letters Moment Menu', 'dbt'::resource_kind, 'A menu built on the IMPROVE letters, where a client picks ways to get through a hard moment.', 'Use it to help a client choose a way to get through a hard moment without making it worse.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through imagery, meaning, prayer or peace, relaxation, one thing in the moment, vacation and encouragement. The client circles what appeals and writes a concrete version of each. Practice one in session so it feels real. Keep a copy handy where the client can see it.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I want a plan for"}, {"id": "f1", "type": "textarea", "label": "Imagery I could use"}, {"id": "f2", "type": "textarea", "label": "A meaning I can find in it"}, {"id": "f3", "type": "textarea", "label": "One thing I can do in the moment"}, {"id": "f4", "type": "textarea", "label": "A short break I can take"}, {"id": "f5", "type": "textarea", "label": "An encouraging thing I can say to myself"}]'::jsonb, array['core DBT', 'distress tolerance', 'skills']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('fast-skills-self-respect-sheet', 'FAST Skills Self-Respect Sheet', 'dbt'::resource_kind, 'A worksheet using fair, apologies, stick to values and truthful for a conversation where self-respect is at stake.', 'Use it to help a client keep their self-respect in a conversation without over-apologizing.', array['Adults', 'Teens']::text[], '25 minutes', 'Take a situation where the client tends to give in or over-explain. Walk through being fair, not apologizing unless it is needed, sticking to values and being truthful. Role-play a line or two. Clients often notice how much they apologize by habit; point it out gently.', '[{"id": "f0", "type": "textarea", "label": "The conversation I am preparing for"}, {"id": "f1", "type": "textarea", "label": "What being fair looks like here"}, {"id": "f2", "type": "textarea", "label": "What I do not need to apologize for"}, {"id": "f3", "type": "textarea", "label": "The value I want to stick to"}, {"id": "f4", "type": "textarea", "label": "The truthful thing I will say"}, {"id": "f5", "type": "textarea", "label": "How I will feel afterward if I do it"}]'::jsonb, array['core DBT', 'interpersonal effectiveness', 'self-respect']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('check-the-facts-flowchart', 'Check the Facts Flowchart', 'dbt'::resource_kind, 'A flowchart that moves from an emotion to the event, the interpretation and whether the facts fit.', 'Use it to help a client check whether their emotion fits the facts of a situation.', array['Adults', 'Teens']::text[], '25 minutes', 'Start with the emotion, then what happened in plain words, and the story the client told about it. Ask what is fact and what is interpretation. If the facts fit the emotion, problem-solve; if not, practice acting opposite. Keep the tone curious so the client does not feel told their feelings are wrong.', '[{"id": "f0", "type": "textarea", "label": "The emotion and how strong it is (0 to 10)"}, {"id": "f1", "type": "textarea", "label": "What happened, in facts only"}, {"id": "f2", "type": "textarea", "label": "The story I told myself about it"}, {"id": "f3", "type": "textarea", "label": "Facts that fit or do not fit that story"}, {"id": "f4", "type": "textarea", "label": "Does my emotion fit the facts?"}, {"id": "f5", "type": "textarea", "label": "What I will do next"}]'::jsonb, array['core DBT', 'emotion regulation', 'check the facts']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('act-opposite-week-log', 'Act Opposite Week Log', 'dbt'::resource_kind, 'A log for trying the opposite of an emotion urge and noting what happened afterward.', 'Use it to help a client try acting opposite to an unhelpful urge and see what changes.', array['Adults', 'Teens']::text[], 'One week', 'Pick an emotion whose urge is not helping, such as withdrawing when sad. The client names the urge, plans the opposite step and notes both the feeling before and after. Fully committing to the step matters, including body posture and tone. Review the log for patterns rather than perfection.', '[{"id": "f0", "type": "textarea", "label": "The emotion and the urge"}, {"id": "f1", "type": "textarea", "label": "The opposite action I planned"}, {"id": "f2", "type": "textarea", "label": "Feeling before (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "Feeling after (0 to 10)"}, {"id": "f5", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['core DBT', 'emotion regulation', 'opposite action']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-the-relationship-chat', 'Weekly State of the Relationship Chat', 'couples'::resource_kind, 'A short weekly check-in with parts for each partner and a shared plan.', 'Use it to give a couple a steady, calm time each week to say what is working and what needs care.', array['Couples']::text[], '30 minutes weekly', 'Each partner fills their own side first, then they take turns reading aloud with no interrupting. Partner A shares one appreciation and one request, then Partner B does the same. End by agreeing on one small thing to do this week. If it gets heated, pause and return to it later.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I appreciated this week"}, {"id": "f1", "type": "textarea", "label": "Partner A: one request for next week"}, {"id": "f2", "type": "textarea", "label": "Partner B: something I appreciated this week"}, {"id": "f3", "type": "textarea", "label": "Partner B: one request for next week"}, {"id": "f4", "type": "textarea", "label": "Together: one thing we will do this week"}]'::jsonb, array['couples', 'communication', 'connection']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('gentle-opening-rewrite-sheet-for-partners', 'Gentle Opening Rewrite Sheet for Partners', 'couples'::resource_kind, 'A sheet where each partner rewrites a harsh complaint as a gentle opening.', 'Use it to help partners raise a concern without opening with blame.', array['Couples']::text[], '25 minutes', 'Each partner picks a recent complaint and writes how it came out. Then they rewrite it using "I feel... about... and I need...". Take turns reading the new versions to each other. Coach the listener to just receive it first. Expect some awkwardness; practicing aloud helps.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I said it before"}, {"id": "f1", "type": "textarea", "label": "Partner A: my soft version"}, {"id": "f2", "type": "textarea", "label": "Partner B: how I said it before"}, {"id": "f3", "type": "textarea", "label": "Partner B: my soft version"}, {"id": "f4", "type": "textarea", "label": "What we noticed when we heard the new versions"}]'::jsonb, array['couples', 'Gottman', 'communication']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('shared-meaning-rituals-page', 'Shared Meaning Rituals Page', 'couples'::resource_kind, 'A page where partners list daily and weekly rituals that matter to them and choose one to start.', 'Use it to help a couple build small shared rituals that bring them closer.', array['Couples']::text[], '30 minutes', 'Each partner lists rituals they remember, enjoy or would like, such as a morning coffee or a walk. Compare lists and look for overlap. Choose one to try for two weeks. Rituals work when they are small and repeatable, not grand.', '[{"id": "f0", "type": "textarea", "label": "Partner A: rituals I enjoy or miss"}, {"id": "f1", "type": "textarea", "label": "Partner B: rituals I enjoy or miss"}, {"id": "f2", "type": "textarea", "label": "Where our lists overlap"}, {"id": "f3", "type": "textarea", "label": "The one we will try for two weeks"}, {"id": "f4", "type": "textarea", "label": "When and where we will do it"}]'::jsonb, array['couples', 'Gottman', 'connection']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('partner-repair-phrase-menu', 'Partner Repair Phrase Menu', 'couples'::resource_kind, 'A menu of phrases and gestures each partner prefers for calming a tense moment.', 'Use it to help partners agree ahead of time on ways to repair during a disagreement.', array['Couples']::text[], '20 minutes', 'Each partner picks the repairs that feel good to them, such as "can we start over" or a hand on the shoulder, and marks any that feel bad. Share lists and agree on a few to use. Practice one in session. Repairs work best when both agree on them before an argument.', '[{"id": "f0", "type": "textarea", "label": "Partner A: repairs that help me"}, {"id": "f1", "type": "textarea", "label": "Partner A: repairs that do not help me"}, {"id": "f2", "type": "textarea", "label": "Partner B: repairs that help me"}, {"id": "f3", "type": "textarea", "label": "Partner B: repairs that do not help me"}, {"id": "f4", "type": "textarea", "label": "The ones we both agree to try"}]'::jsonb, array['couples', 'Gottman', 'repair']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('division-of-daily-tasks-talk-sheet', 'Division of Daily Tasks Talk Sheet', 'couples'::resource_kind, 'A sheet for naming the tasks each partner carries and talking about how fair it feels.', 'Use it to help a couple talk about who does what in a way that avoids score-keeping.', array['Couples']::text[], '30 minutes', 'Each partner lists the visible and invisible tasks they do, including planning and remembering. Compare lists and ask how each feels about the share. Avoid tallying; the aim is to understand. Choose one task to shift or share. Revisit in a month.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I carry, including the invisible ones"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I carry, including the invisible ones"}, {"id": "f2", "type": "textarea", "label": "How the share feels to each of us"}, {"id": "f3", "type": "textarea", "label": "One task we will shift or share"}, {"id": "f4", "type": "textarea", "label": "When we will check back in"}]'::jsonb, array['couples', 'relationship issues', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('worry-monster-drawing-and-feeding-box', 'Worry Monster Drawing and Feeding Box', 'kids'::resource_kind, 'A craft where a child draws a worry monster and feeds it folded worries through a slot in a box.', 'Use it to give a child a playful way to name worries and set them outside themselves.', array['Children']::text[], '30 minutes', 'Help the child decorate a small box with a mouth. They draw or write worries on slips and feed them in. Tell the parent they can use the box at home at bedtime and read the slips only if the child invites it. Keep the tone playful, and follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your worry monster"}, {"id": "f1", "type": "textarea", "label": "What does it like to eat?"}, {"id": "f2", "type": "textarea", "label": "A worry I fed it today"}, {"id": "f3", "type": "textarea", "label": "How my body feels after feeding it"}, {"id": "f4", "type": "textarea", "label": "Where we keep the box at home"}]'::jsonb, array['children', 'worry', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-glitter-build', 'Calm Down Jar Glitter Build', 'kids'::resource_kind, 'A build-it activity where a child makes a glitter jar and watches it settle as they breathe.', 'Use it to give a child a visual way to notice that big feelings settle with time and breath.', array['Children']::text[], '25 minutes', 'Make the jar together with water, clear glue and glitter, sealed tightly. Shake it for the feeling and breathe while it settles. Tell the parent to offer the jar as an invitation, never as a punishment. Practice when calm so it is easy to use when upset.', '[{"id": "f0", "type": "textarea", "label": "The feeling I shook into my jar"}, {"id": "f1", "type": "textarea", "label": "What my glitter looked like"}, {"id": "f2", "type": "textarea", "label": "How my breathing felt while it settled"}, {"id": "f3", "type": "textarea", "label": "When I might use my jar"}, {"id": "f4", "type": "textarea", "label": "What my grown-up can do to help"}]'::jsonb, array['children', 'regulation', 'play', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('feelings-weather-sliding-window-craft', 'Feelings Weather Sliding Window Craft', 'kids'::resource_kind, 'A craft with a paper window the child slides to show today''s feelings as weather.', 'Use it to help a child show and name feelings through weather pictures.', array['Children']::text[], '25 minutes', 'Draw a sunny, cloudy, rainy and stormy scene on strips and slide them behind a cut-out window. The child shows how they feel at check-in. Ask the parent to look at it once a day and say "thanks for showing me". Weather changes, which is a helpful message in itself.', '[{"id": "f0", "type": "textarea", "label": "Today''s weather inside me"}, {"id": "f1", "type": "textarea", "label": "Why it is that weather"}, {"id": "f2", "type": "textarea", "label": "A time it changed"}, {"id": "f3", "type": "textarea", "label": "What helps when it is stormy"}, {"id": "f4", "type": "textarea", "label": "Who I can show my window to"}]'::jsonb, array['children', 'emotion identification', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('brave-steps-sticker-ladder-poster', 'Brave Steps Sticker Ladder Poster', 'kids'::resource_kind, 'A poster where a child draws a ladder of small brave steps and adds a sticker for each one tried.', 'Use it to help a child break a hard thing into small steps they can try one at a time.', array['Children']::text[], '30 minutes', 'Choose one thing the child wants to get better at and draw a ladder with five rungs, smallest at the bottom. The child decorates it and colors a rung after each try. Tell the parent to cheer for trying, not for how it went. Rungs can be re-ordered if one is too big.', '[{"id": "f0", "type": "textarea", "label": "The thing I want to get braver about"}, {"id": "f1", "type": "textarea", "label": "My smallest step"}, {"id": "f2", "type": "textarea", "label": "The next steps up my ladder"}, {"id": "f3", "type": "textarea", "label": "What I tell myself when it is hard"}, {"id": "f4", "type": "textarea", "label": "How my grown-up can cheer for me"}]'::jsonb, array['children', 'exposure', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('kindness-seeds-garden-craft', 'Kindness Seeds Garden Craft', 'kids'::resource_kind, 'A paper garden where a child plants a seed for each kind thing they notice or do.', 'Use it to help a child notice kindness given and received, including toward themselves.', array['Children']::text[], 'One week', 'Give the child a paper garden and seed stickers. Each kind act, small or large, gets a seed and a few words. Invite one seed for something kind to themselves. Ask the parent to add a seed when they see kindness. Look at the garden together at the next session.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I did"}, {"id": "f1", "type": "textarea", "label": "A kind thing someone did for me"}, {"id": "f2", "type": "textarea", "label": "A kind thing I did for myself"}, {"id": "f3", "type": "textarea", "label": "How it felt to plant it"}, {"id": "f4", "type": "textarea", "label": "What I want my garden to look like"}]'::jsonb, array['children', 'strengths', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('opposite-day-emotion-charades', 'Opposite Day Emotion Charades', 'game'::resource_kind, 'A group game of acting out an emotion and then the opposite action.', 'Use it to help a group see what acting opposite to an emotion looks and feels like.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Write emotions on cards. A player draws one and acts it out, then the group guesses. The player then acts the opposite action, such as approaching instead of hiding. After a few rounds, debrief: which was easier to act, and how did the body feel in each? Rules: no words, and everyone gets a turn.', '[{"id": "f0", "type": "textarea", "label": "The emotion I acted"}, {"id": "f1", "type": "textarea", "label": "The opposite action I acted"}, {"id": "f2", "type": "textarea", "label": "Which was easier and why"}, {"id": "f3", "type": "textarea", "label": "What my body felt in each"}, {"id": "f4", "type": "textarea", "label": "When I could try the opposite in real life"}]'::jsonb, array['game', 'emotion regulation', 'group', 'opposite action']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('thought-traps-bingo', 'Thought Traps Bingo', 'game'::resource_kind, 'A bingo game where players mark common thinking traps as the leader reads everyday examples.', 'Use it to help a group learn to recognize common thinking traps in everyday situations.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make bingo cards with traps such as mind reading, catastrophizing and all-or-nothing thinking. Read short examples and let players mark the trap they hear. Turns pass round the circle, and a winner is the first row. Debrief by asking which trap each person notices most in their own thinking.', '[{"id": "f0", "type": "textarea", "label": "The trap I noticed most in the game"}, {"id": "f1", "type": "textarea", "label": "An example from my own life"}, {"id": "f2", "type": "textarea", "label": "How I could answer that thought"}, {"id": "f3", "type": "textarea", "label": "A trap I want to watch for this week"}]'::jsonb, array['game', 'thinking traps', 'group', 'core CBT']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('values-bidding-auction-game', 'Values Bidding Auction Game', 'game'::resource_kind, 'A group game where players use play money to bid on values and see what they are willing to give up.', 'Use it to help a group see which values matter most when they have to choose.', array['Teens', 'Adults', 'Groups']::text[], '40 minutes', 'Give each player the same amount of play money and a list of values to bid on. Take turns as auctioneer, and bids close when no one raises. Afterward debrief: what did you spend on, what did you let go, and what surprised you? There are no wrong values, only a picture of what matters today.', '[{"id": "f0", "type": "textarea", "label": "What I spent most of my money on"}, {"id": "f1", "type": "textarea", "label": "A value I let go and how that felt"}, {"id": "f2", "type": "textarea", "label": "What surprised me"}, {"id": "f3", "type": "textarea", "label": "One way I could live a top value this week"}]'::jsonb, array['game', 'values', 'group', 'core ACT']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('skills-toolbox-relay', 'Skills Toolbox Relay', 'game'::resource_kind, 'A relay game where teams race to match coping skills to situations on cards.', 'Use it to help a group practice matching coping skills to the situations they fit.', array['Children', 'Teens', 'Groups']::text[], '25 minutes', 'Make situation cards and skill cards. Teams take turns sending a runner to pick a situation and place a skill that fits it. The team agrees on an answer before the next runner goes. The aim is a good match, not speed alone. In debrief, ask which skills they would really use.', '[{"id": "f0", "type": "textarea", "label": "The skill I would most use"}, {"id": "f1", "type": "textarea", "label": "A situation I matched it to"}, {"id": "f2", "type": "textarea", "label": "A skill I want to learn more about"}, {"id": "f3", "type": "textarea", "label": "How I will remember it"}]'::jsonb, array['game', 'coping skills', 'group', 'skills']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('flashlight-strengths-circle', 'Flashlight Strengths Circle', 'game'::resource_kind, 'A circle game where each player is the spotlight while others name a real strength they have seen.', 'Use it to help a group give and receive specific, honest recognition of strengths.', array['Children', 'Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Pass a flashlight around. The spotlight player sits quietly while each other member names one strength and an example. The receiver says "thank you" only. Rules: be specific, be true, and no "but". Debrief on how it felt to hear it and which strengths surprised them.', '[{"id": "f0", "type": "textarea", "label": "A strength someone named in me"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it"}, {"id": "f2", "type": "textarea", "label": "A strength I named in someone else"}, {"id": "f3", "type": "textarea", "label": "A strength I want to use this week"}]'::jsonb, array['game', 'strengths', 'group', 'self-esteem']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('safe-and-settled-things-list-page', 'Safe and Settled Things List Page', 'worksheet'::resource_kind, 'A page where a client lists places, objects and sensations that feel safe and settled to them.', 'Use it to help a client build a personal list of things that bring a sense of safety.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep the focus on the present: what feels safe now, not on what happened. Ask for sights, sounds, textures and people. If a listed item brings up something hard, set it aside without comment and choose another. Clients can keep the page where they will see it.', '[{"id": "f0", "type": "textarea", "label": "A place that feels safe or calm to me"}, {"id": "f1", "type": "textarea", "label": "Something I can see there"}, {"id": "f2", "type": "textarea", "label": "Something I can hear or feel there"}, {"id": "f3", "type": "textarea", "label": "Someone or something that helps me feel safe"}, {"id": "f4", "type": "textarea", "label": "One way to bring a piece of it into my day"}]'::jsonb, array['PTSD and trauma', 'safety', 'grounding', 'pacing']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('stuck-thought-gentle-reframe-sheet', 'Stuck Thought Gentle Reframe Sheet', 'cbt'::resource_kind, 'A sheet for noticing a hard "stuck" thought and writing a kinder, more balanced one beside it.', 'Use it to help a client notice stuck thoughts about safety or self-blame and practice a balanced alternative.', array['Adults']::text[], '25 minutes', 'Work with a present-day thought, such as "I am never safe", not the details of an event. Ask the client to rate belief, then write what a trusted friend might say. Keep the pace slow and pause to ground if needed. Do not ask for a written account of what happened.', '[{"id": "f0", "type": "textarea", "label": "A thought that keeps coming back"}, {"id": "f1", "type": "textarea", "label": "How strongly I believe it today (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What a trusted friend might say to me"}, {"id": "f3", "type": "textarea", "label": "A more balanced thought"}, {"id": "f4", "type": "textarea", "label": "How I feel when I read it"}]'::jsonb, array['PTSD and trauma', 'core CBT', 'self-blame', 'safety']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('making-room-for-hard-memories-page', 'Making Room for Hard Memories Page', 'act'::resource_kind, 'A page for practicing making room for a hard memory''s feelings at the edge of attention, with an anchor for the present.', 'Use it to help a client practice staying present with a hard feeling without being pulled into it.', array['Adults']::text[], '20 minutes', 'Keep this to feelings and sensations in the present moment, not a retelling. Pair each noticing with an anchor, such as feet on the floor. Agree beforehand on a stop signal and use it freely. Short and repeatable beats long.', '[{"id": "f0", "type": "textarea", "label": "A feeling I noticed in my body"}, {"id": "f1", "type": "textarea", "label": "Where in my body I felt it"}, {"id": "f2", "type": "textarea", "label": "My anchor in the present"}, {"id": "f3", "type": "textarea", "label": "What I did to make a little room for it"}, {"id": "f4", "type": "textarea", "label": "What I want to do with my day after this"}]'::jsonb, array['PTSD and trauma', 'core ACT', 'grounding', 'pacing']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('temperature-change-cooling-card', 'Temperature Change Cooling Card', 'dbt'::resource_kind, 'A card for using cold water or a cool pack to bring down intense body activation.', 'Use it to give a client a quick body-based option for a surge of intense feeling.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach it in session first: cool water on the face, or a cold pack held for a short time while breathing out slowly. Check with the client about health concerns first, and use their judgment. Have them record what they used and how it went.', '[{"id": "f0", "type": "textarea", "label": "What was happening when I needed this"}, {"id": "f1", "type": "textarea", "label": "What I used to cool down"}, {"id": "f2", "type": "textarea", "label": "My feeling level before (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "My feeling level after (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "Where I will keep what I need"}]'::jsonb, array['PTSD and trauma', 'core DBT', 'distress tolerance', 'grounding']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('hard-day-support-preferences-plan', 'Hard Day Support Preferences Plan', 'couples'::resource_kind, 'A plan where each partner says what helps and what does not on a hard day.', 'Use it to help partners agree on how to support each other when one is having a rough day.', array['Couples']::text[], '30 minutes', 'Each partner lists what helps and what does not, with no need to explain why. The supportive partner reads it back. Agree on a signal for needing space and one for needing company. Neither partner is asked to share details of anything painful.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps on a hard day"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what helps on a hard day"}, {"id": "f3", "type": "textarea", "label": "Partner B: what does not help"}, {"id": "f4", "type": "textarea", "label": "Our signals for space and company"}]'::jsonb, array['PTSD and trauma', 'couples', 'support', 'communication']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('anxiety-body-map-coloring-page', 'Anxiety Body Map Coloring Page', 'kids'::resource_kind, 'A body outline the child colors to show where worry feels like it lives.', 'Use it to help a child notice where worry shows up in the body.', array['Children']::text[], '25 minutes', 'Hand the child crayons and a body outline and ask where worry feels strong. Let them choose colors and shapes freely. Tell the parent that the page is for noticing, and that they can ask about colors at home. Close with a calming breath, such as smelling a flower.', '[{"id": "f0", "type": "textarea", "label": "Color where worry lives in my body"}, {"id": "f1", "type": "textarea", "label": "The color I picked for worry"}, {"id": "f2", "type": "textarea", "label": "What worry feels like there"}, {"id": "f3", "type": "textarea", "label": "What helps that spot feel better"}, {"id": "f4", "type": "textarea", "label": "Who I can tell when I feel it"}]'::jsonb, array['anxiety', 'children', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('worry-or-wise-sorting-game', 'Worry or Wise Sorting Game', 'game'::resource_kind, 'A card game where players sort thoughts into worry voice and wise voice.', 'Use it to help a group tell worried thoughts from wiser, more balanced ones.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Write thoughts on cards, such as "everything will go wrong". Players take turns drawing one, placing it in the worry or wise pile, and defending the choice. For worry cards, the player writes a wiser version. Debrief: which worry voice sounds most like yours?', '[{"id": "f0", "type": "textarea", "label": "A worry card that sounded like me"}, {"id": "f1", "type": "textarea", "label": "A wiser version I wrote"}, {"id": "f2", "type": "textarea", "label": "How I feel reading the wise version"}, {"id": "f3", "type": "textarea", "label": "A worry I want to answer this week"}]'::jsonb, array['anxiety', 'game', 'thinking traps', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('avoidance-costs-and-gains-ledger', 'Avoidance Costs and Gains Ledger', 'worksheet'::resource_kind, 'A ledger where a client lists what they avoid, what it gives them now, and what it costs over time.', 'Use it to help a client see the short-term gains and long-term costs of avoiding.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for three things the client avoids, then fill in what avoidance gives and what it takes away. The ledger is not a judgment. Look at the costs together and pick one avoided thing to approach in a small way. Revisit after a week.', '[{"id": "f0", "type": "textarea", "label": "Something I avoid"}, {"id": "f1", "type": "textarea", "label": "What avoiding gives me right away"}, {"id": "f2", "type": "textarea", "label": "What avoiding costs me over time"}, {"id": "f3", "type": "textarea", "label": "A small step toward it"}, {"id": "f4", "type": "textarea", "label": "What I will do this week"}]'::jsonb, array['anxiety', 'avoidance', 'exposure', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('not-knowing-small-steps-log', 'Not Knowing Small Steps Log', 'cbt'::resource_kind, 'A log for trying a small step in uncertainty and recording how it felt and what happened.', 'Use it to help a client practice tolerating not knowing in small, planned steps.', array['Adults', 'Teens']::text[], 'One week', 'Choose a low-risk step, such as not checking a message for an hour. The client predicts what will happen, tries it and records the result. Review both what happened and how the feeling rose and fell. Increase difficulty only when the client is ready.', '[{"id": "f0", "type": "textarea", "label": "The uncertain situation I tried"}, {"id": "f1", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f2", "type": "textarea", "label": "What I felt, and how strongly (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I noticed about not knowing"}]'::jsonb, array['anxiety', 'core CBT', 'behavioral experiment', 'worry']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('worry-passengers-on-the-bus-worksheet', 'Worry Passengers on the Bus Worksheet', 'act'::resource_kind, 'A worksheet using the passengers-on-the-bus image to practice carrying worry while driving toward a value.', 'Use it to help a client keep moving toward what matters while worries ride along.', array['Adults', 'Teens']::text[], '25 minutes', 'Describe the bus: the client drives, and worries are noisy passengers who cannot take the wheel. They name a destination tied to a value and a few passengers. The passengers may keep talking; the client keeps driving. Ask what the client wants to do at the next stop.', '[{"id": "f0", "type": "textarea", "label": "Where I want my bus to go"}, {"id": "f1", "type": "textarea", "label": "The loudest passenger and what it says"}, {"id": "f2", "type": "textarea", "label": "What I do when it shouts"}, {"id": "f3", "type": "textarea", "label": "A small step I can take toward my destination"}, {"id": "f4", "type": "textarea", "label": "What I would say to a passenger who will not quiet down"}]'::jsonb, array['anxiety', 'core ACT', 'defusion', 'values']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('accumulating-positives-weekly-plan', 'Accumulating Positives Weekly Plan', 'dbt'::resource_kind, 'A weekly plan that schedules short-term pleasant events and long-term steps toward what matters.', 'Use it to help a client add pleasant moments and a longer-term step into a low-energy week.', array['Adults', 'Teens']::text[], 'One week', 'Choose small events the client can do in 10 minutes. Add one longer-term step toward a value. Ask them to note being fully present for the event, since attention is part of the skill. If energy is very low, start with one event.', '[{"id": "f0", "type": "textarea", "label": "A pleasant event I can do this week"}, {"id": "f1", "type": "textarea", "label": "When I will do it"}, {"id": "f2", "type": "textarea", "label": "A longer-term step toward something I care about"}, {"id": "f3", "type": "textarea", "label": "What I noticed while doing it"}, {"id": "f4", "type": "textarea", "label": "What got in the way"}]'::jsonb, array['depression', 'core DBT', 'emotion regulation', 'behavioral activation']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('low-mood-partner-check-in-cards', 'Low Mood Partner Check-In Cards', 'couples'::resource_kind, 'A set of cards where partners say how they are doing and what they need.', 'Use it to help partners talk about low mood without pressure to fix it.', array['Couples']::text[], '25 minutes', 'The partner with low mood picks a card, such as "I need quiet" or "I need a walk", and the other partner responds. Practice in session. If either partner mentions thoughts of self-harm, stop and follow your safety steps, and remind them of 988, which they can call or text.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a card I would use"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I will respond to it"}, {"id": "f2", "type": "textarea", "label": "Partner B: a card I would use"}, {"id": "f3", "type": "textarea", "label": "Partner A: how I will respond to it"}, {"id": "f4", "type": "textarea", "label": "If things feel unsafe, we call or text 988 and tell..."}]'::jsonb, array['depression', 'couples', 'support', 'communication']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('feelings-mountain-painting-activity', 'Feelings Mountain Painting Activity', 'kids'::resource_kind, 'A painting where a child shows sad and heavy feelings as parts of a mountain scene.', 'Use it to help a child show heavy feelings through color and a scene.', array['Children']::text[], '30 minutes', 'Offer paint and paper and ask for a mountain with weather. The child chooses what the clouds, valleys and sunny spots stand for. Tell the parent that the painting is a way to start a talk, and not to ask for explanations. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Paint your mountain"}, {"id": "f1", "type": "textarea", "label": "What the clouds stand for"}, {"id": "f2", "type": "textarea", "label": "What the sunny spot stands for"}, {"id": "f3", "type": "textarea", "label": "What I do when the weather is heavy"}, {"id": "f4", "type": "textarea", "label": "Who I can sit with when it is cloudy"}]'::jsonb, array['depression', 'children', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('small-wins-scavenger-hunt', 'Small Wins Scavenger Hunt', 'game'::resource_kind, 'A scavenger hunt where players collect small good moments from their week.', 'Use it to help a group notice small good moments that are easy to miss when mood is low.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Each player gets a list of prompts like "something that made me smile" or "a thing I got done". They take turns reading what they found. Rules: small counts, and nobody has to fill every line. Debrief on which prompts were hardest.', '[{"id": "f0", "type": "textarea", "label": "A small win I found this week"}, {"id": "f1", "type": "textarea", "label": "A prompt I could not fill"}, {"id": "f2", "type": "textarea", "label": "What I notice about small moments"}, {"id": "f3", "type": "textarea", "label": "One I want to look for this week"}]'::jsonb, array['depression', 'game', 'positive psychology', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('doing-and-feeling-link-chart', 'Doing and Feeling Link Chart', 'worksheet'::resource_kind, 'A chart where a client rates mood and mastery alongside daily activities to see patterns.', 'Use it to help a client see how what they do links with how they feel.', array['Adults', 'Teens']::text[], 'One week', 'The client records an activity and rates mood and sense of accomplishment for each part of the day. At review, look for activities that lift or drop mood without judging. Choose one that lifted to add more of. Keep entries brief so it is doable.', '[{"id": "f0", "type": "textarea", "label": "The activity"}, {"id": "f1", "type": "textarea", "label": "Mood during it (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "Sense of accomplishment (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "An activity that lifted my mood"}, {"id": "f4", "type": "textarea", "label": "One I want to add this week"}]'::jsonb, array['depression', 'behavioral activation', 'self-monitoring', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('tiny-first-step-task-ladder', 'Tiny First Step Task Ladder', 'cbt'::resource_kind, 'A worksheet that breaks a dreaded task into a ladder of tiny first steps.', 'Use it to help a client get a task started by shrinking the first step.', array['Adults', 'Teens']::text[], '25 minutes', 'Choose one task the client keeps putting off. Break it down until the first step takes under two minutes, then rank the steps. The client picks a time to try the first rung. Review what made it easier or harder, and adjust the ladder.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "The tiniest first step"}, {"id": "f2", "type": "textarea", "label": "The next three steps"}, {"id": "f3", "type": "textarea", "label": "When I will try step one"}, {"id": "f4", "type": "textarea", "label": "What might get in the way and what I will do"}]'::jsonb, array['ADHD', 'core CBT', 'planning', 'routines']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('boring-but-valued-tasks-page', 'Boring but Valued Tasks Page', 'act'::resource_kind, 'A page connecting a dull task to the value behind it and a way to carry the boredom.', 'Use it to help a client do a tedious task by linking it to something they care about.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one tedious task and ask what it makes possible. The client names the value and the feeling of boredom, then plans how to make room for it, such as a timer or music. Willingness to be bored is the skill, not liking the task.', '[{"id": "f0", "type": "textarea", "label": "The task I find boring"}, {"id": "f1", "type": "textarea", "label": "What it makes possible for me"}, {"id": "f2", "type": "textarea", "label": "The value behind it"}, {"id": "f3", "type": "textarea", "label": "How I will make room for the boredom"}, {"id": "f4", "type": "textarea", "label": "A reward or pause I will take after"}]'::jsonb, array['ADHD', 'core ACT', 'values', 'willingness']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('impulse-pause-and-choose-card', 'Impulse Pause and Choose Card', 'dbt'::resource_kind, 'A card for pausing before acting on an impulse and picking a response.', 'Use it to help a client slow down between an impulse and what they do next.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach a short pause, such as counting a breath, then asking what the impulse wants and what the client wants. They write the options and pick one. Practice with a low-stakes example. The goal is a gap, not never acting on impulse.', '[{"id": "f0", "type": "textarea", "label": "The impulse I noticed"}, {"id": "f1", "type": "textarea", "label": "What it wants me to do"}, {"id": "f2", "type": "textarea", "label": "What I want for later"}, {"id": "f3", "type": "textarea", "label": "Two other options"}, {"id": "f4", "type": "textarea", "label": "What I chose and how it went"}]'::jsonb, array['ADHD', 'core DBT', 'regulation', 'executive skills']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('shared-reminder-system-planner', 'Shared Reminder System Planner', 'couples'::resource_kind, 'A planner where partners agree on reminders and who holds which task, without nagging.', 'Use it to help partners build a reminder system they both feel okay with.', array['Couples']::text[], '30 minutes', 'Each partner lists tasks that slip and how they would like to be reminded. Agree on tools, such as a shared calendar or a note at the door, and on tone. Decide how a missed reminder is handled. Check back on what works after two weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks that slip and how I would like to be reminded"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks that slip and how I would like to be reminded"}, {"id": "f2", "type": "textarea", "label": "The system we choose"}, {"id": "f3", "type": "textarea", "label": "What we say when a reminder is missed"}, {"id": "f4", "type": "textarea", "label": "When we will adjust it"}]'::jsonb, array['ADHD', 'couples', 'relationship issues', 'routines']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('morning-routine-picture-strip-craft', 'Morning Routine Picture Strip Craft', 'kids'::resource_kind, 'A craft where a child draws or photographs each morning step on a strip they can follow.', 'Use it to give a child a picture guide for a morning routine they help to design.', array['Children']::text[], '30 minutes', 'The child draws or poses for each step, such as getting dressed, and glues the pictures in order on a strip. Tell the parent to point to the strip instead of repeating instructions, and to praise steps done. Adjust the strip with the child after a week.', '[{"id": "f0", "type": "textarea", "label": "The steps in my morning"}, {"id": "f1", "type": "textarea", "label": "Which step is hardest"}, {"id": "f2", "type": "textarea", "label": "A way to make it easier"}, {"id": "f3", "type": "textarea", "label": "What my grown-up will do to help"}, {"id": "f4", "type": "textarea", "label": "How I will feel when I finish"}]'::jsonb, array['ADHD', 'children', 'routines', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('refusal-skills-card-game', 'Refusal Skills Card Game', 'game'::resource_kind, 'A card game where players draw situations and practice saying no to substance use offers.', 'Use it to help a group rehearse ways to decline substance use in a pressure moment.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'Make cards with situations and with refusal styles, such as a direct no, a change of subject or leaving. Players draw both, role-play for 30 seconds and rate how it felt. Turns rotate, and the group offers tips. Debrief on which style fits each person.', '[{"id": "f0", "type": "textarea", "label": "A situation I drew and what I said"}, {"id": "f1", "type": "textarea", "label": "A refusal style that felt natural"}, {"id": "f2", "type": "textarea", "label": "One that felt awkward"}, {"id": "f3", "type": "textarea", "label": "A situation I will plan for this week"}]'::jsonb, array['addiction', 'game', 'substance use', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('urge-surfing-wave-tracker', 'Urge Surfing Wave Tracker', 'worksheet'::resource_kind, 'A tracker where a client notes an urge, rides it out and rates how it rose and fell.', 'Use it to help a client see that urges for substance use rise, peak and pass.', array['Adults', 'Teens']::text[], 'One week', 'Teach the wave image in session. The client logs each urge, what set it off, the peak rating and how long until it eased. Look for the pattern of rising and falling. Note what helped, like moving or calling someone, and plan to use it.', '[{"id": "f0", "type": "textarea", "label": "What set off the urge"}, {"id": "f1", "type": "textarea", "label": "How strong it got (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What I did while it was there"}, {"id": "f3", "type": "textarea", "label": "How long until it eased"}, {"id": "f4", "type": "textarea", "label": "What I would do again"}]'::jsonb, array['addiction', 'urges', 'substance use', 'self-monitoring']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('triggers-thoughts-and-choices-chain', 'Triggers, Thoughts and Choices Chain', 'cbt'::resource_kind, 'A chain from a trigger to a thought, an urge and the choices at each link.', 'Use it to help a client find the points in a chain where a different choice is possible.', array['Adults', 'Teens']::text[], '30 minutes', 'Take a recent urge for substance use and lay out the chain: trigger, thought, feeling, urge and action. At each link, ask what else the client could have done. Choose a link to practice changing. Keep a nonjudgmental tone throughout.', '[{"id": "f0", "type": "textarea", "label": "The trigger"}, {"id": "f1", "type": "textarea", "label": "The thought that came"}, {"id": "f2", "type": "textarea", "label": "The feeling and the urge"}, {"id": "f3", "type": "textarea", "label": "What I did"}, {"id": "f4", "type": "textarea", "label": "A different choice at one of the links"}]'::jsonb, array['addiction', 'core CBT', 'urges', 'substance use']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('life-beyond-substance-use-values-page', 'Life Beyond Substance Use Values Page', 'act'::resource_kind, 'A page where a client names the values and life areas they want to move toward.', 'Use it to help a client connect with what they care about beyond substance use.', array['Adults']::text[], '25 minutes', 'Ask about relationships, work, health and play and what the client wants in each. Then ask what their substance use has done to those areas, without blame. Pick one area and one small action. Return to the page when urges are strong.', '[{"id": "f0", "type": "textarea", "label": "What matters to me in my relationships"}, {"id": "f1", "type": "textarea", "label": "What matters to me in work or school"}, {"id": "f2", "type": "textarea", "label": "What matters to me in my health"}, {"id": "f3", "type": "textarea", "label": "One small action toward a value this week"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself when an urge shows up"}]'::jsonb, array['addiction', 'core ACT', 'values', 'substance use']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('distracting-with-wise-mind-accepts-plan', 'Distracting With Wise Mind ACCEPTS Plan', 'dbt'::resource_kind, 'A plan using the ACCEPTS letters to get through an urge for substance use.', 'Use it to give a client a menu of ways to ride out an urge.', array['Adults', 'Teens']::text[], '20 minutes', 'Go through activities, contributing, comparisons, emotions, pushing away, thoughts and sensations. The client picks two or three and writes a specific version of each, such as a person to call. Practice one in session. Keep the plan where they can reach it.', '[{"id": "f0", "type": "textarea", "label": "An activity I can do instead"}, {"id": "f1", "type": "textarea", "label": "Someone I can contribute to or call"}, {"id": "f2", "type": "textarea", "label": "A feeling I can create, like a funny video"}, {"id": "f3", "type": "textarea", "label": "A sensation I can use, like a cold shower"}, {"id": "f4", "type": "textarea", "label": "Where my plan lives"}]'::jsonb, array['addiction', 'core DBT', 'distress tolerance', 'urges']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('time-out-agreement-for-partners', 'Time-Out Agreement for Partners', 'couples'::resource_kind, 'An agreement where partners decide how and when to pause a heated talk and return to it.', 'Use it to help partners pause an argument safely and come back to it.', array['Couples']::text[], '30 minutes', 'Each partner chooses a pause word, how long a break lasts and what they will do during it. Agree who comes back and when. Practice calling it in session. If either partner feels unsafe, stop and use your safety steps.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my pause word and what I will do"}, {"id": "f1", "type": "textarea", "label": "Partner B: my pause word and what I will do"}, {"id": "f2", "type": "textarea", "label": "How long a break lasts"}, {"id": "f3", "type": "textarea", "label": "Who comes back and when"}, {"id": "f4", "type": "textarea", "label": "What we say when we return"}]'::jsonb, array['anger management', 'couples', 'communication', 'safety']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('paper-volcano-heat-gauge-craft', 'Paper Volcano Heat Gauge Craft', 'kids'::resource_kind, 'A craft where a child builds a paper volcano and draws what helps it cool.', 'Use it to help a child notice rising anger and choose ways to cool down.', array['Children']::text[], '30 minutes', 'Build the volcano and draw a heat gauge up the side. The child marks where they start to feel hot and writes cool-down moves on the lava. Tell the parent to practice moves when calm and to cool down together. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "The sign that I am getting hot"}, {"id": "f1", "type": "textarea", "label": "How hot I get (draw it)"}, {"id": "f2", "type": "textarea", "label": "A cool-down move that works"}, {"id": "f3", "type": "textarea", "label": "A cool-down move I want to try"}, {"id": "f4", "type": "textarea", "label": "What my grown-up will do"}]'::jsonb, array['anger management', 'children', 'regulation', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('anger-ladder-role-play-round', 'Anger Ladder Role Play Round', 'game'::resource_kind, 'A group game of acting out one situation at several levels of anger and a calmer alternative.', 'Use it to help a group see the steps from annoyed to furious and practice stepping off.', array['Teens', 'Adults', 'Groups']::text[], '30 minutes', 'A player picks a situation card and acts it at low, middle and high levels while the group names the signs. They then act a calmer response. Turns rotate. Rules: no touching and no real insults. Debrief on when the choice to step off is easiest.', '[{"id": "f0", "type": "textarea", "label": "A sign my anger is rising"}, {"id": "f1", "type": "textarea", "label": "The step where I could step off"}, {"id": "f2", "type": "textarea", "label": "The calmer response I acted"}, {"id": "f3", "type": "textarea", "label": "A situation I want to practice this week"}]'::jsonb, array['anger management', 'game', 'group', 'regulation']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('anger-triggers-and-underneath-feelings-page', 'Anger Triggers and Underneath Feelings Page', 'worksheet'::resource_kind, 'A page that looks at what sets off anger and the softer feelings that may sit beneath it.', 'Use it to help a client see what sits under anger and what they need.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for a recent moment and what set it off, then what else the client may have felt, such as hurt or fear. Ask what they needed. Some clients resist naming softer feelings, so go gently. Close with one way to ask for the need.', '[{"id": "f0", "type": "textarea", "label": "What set off my anger"}, {"id": "f1", "type": "textarea", "label": "What I felt underneath"}, {"id": "f2", "type": "textarea", "label": "What I needed in that moment"}, {"id": "f3", "type": "textarea", "label": "What I did with my anger"}, {"id": "f4", "type": "textarea", "label": "A way to ask for what I need"}]'::jsonb, array['anger management', 'regulation', 'emotion identification', 'self-monitoring']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('anger-thoughts-and-cooler-thoughts-sheet', 'Anger Thoughts and Cooler Thoughts Sheet', 'cbt'::resource_kind, 'A sheet pairing hot angry thoughts with cooler, more flexible ones.', 'Use it to help a client notice anger-fueling thoughts and practice cooler alternatives.', array['Adults', 'Teens']::text[], '25 minutes', 'Look for "should" statements and mind reading. The client writes the hot thought and then a cooler version. Ask them to rate anger before and after. The aim is not to erase anger but to give them a choice about how to respond.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "My hot thought"}, {"id": "f2", "type": "textarea", "label": "Anger before (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "A cooler thought"}, {"id": "f4", "type": "textarea", "label": "Anger after (0 to 10)"}]'::jsonb, array['anger management', 'core CBT', 'thinking traps']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('unwelcome-thoughts-defusion-page', 'Unwelcome Thoughts Defusion Page', 'act'::resource_kind, 'A page for practicing seeing an intrusive thought as a thought and choosing what to do next.', 'Use it to help a client step back from intrusive thoughts without arguing with them.', array['Adults', 'Teens']::text[], '20 minutes', 'Pick one intrusive thought and try labels such as "I am having the thought that...". The client notes how it feels to name it and then picks a valued action. Avoid reassurance, since it feeds the cycle. Agree that the thought may stay while the client moves on.', '[{"id": "f0", "type": "textarea", "label": "The thought that showed up"}, {"id": "f1", "type": "textarea", "label": "I am having the thought that..."}, {"id": "f2", "type": "textarea", "label": "What it felt like to say it that way"}, {"id": "f3", "type": "textarea", "label": "What I care about right now"}, {"id": "f4", "type": "textarea", "label": "A step I took toward that"}]'::jsonb, array['OCD', 'core ACT', 'defusion', 'intrusive thoughts']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('urge-delay-timer-plan-for-rituals', 'Urge Delay Timer Plan for Rituals', 'dbt'::resource_kind, 'A plan to delay a ritual urge by a few minutes and ride the feeling with a soothing step.', 'Use it to help a client practice waiting before acting on a ritual urge.', array['Adults', 'Teens']::text[], '25 minutes', 'Agree on a delay that is just beyond what feels easy, such as five minutes. The client writes what they will do while waiting, such as a sensory soothing step. They rate the urge at the start and end. Lengthen the delay step by step, at the client''s pace.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed"}, {"id": "f1", "type": "textarea", "label": "How long I will wait"}, {"id": "f2", "type": "textarea", "label": "What I will do while waiting"}, {"id": "f3", "type": "textarea", "label": "Urge at start and end (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the urge"}]'::jsonb, array['OCD', 'core DBT', 'urges', 'distress tolerance']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('reassurance-pattern-partner-agreement', 'Reassurance Pattern Partner Agreement', 'couples'::resource_kind, 'An agreement where partners decide how the partner will respond to repeated requests for reassurance.', 'Use it to help partners respond to reassurance requests in a way that supports the client''s goals.', array['Couples']::text[], '30 minutes', 'The partner who feels pressure to reassure says how it feels. The partner who asks says what they hope for. Agree on a kind line, such as "I care about you and I think you can ride this out". Expect to revise it after trying. Keep the tone warm.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how the requests feel to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I hope for when I ask"}, {"id": "f2", "type": "textarea", "label": "The kind line we will use"}, {"id": "f3", "type": "textarea", "label": "What we do instead of reassuring"}, {"id": "f4", "type": "textarea", "label": "When we will review how it is going"}]'::jsonb, array['OCD', 'couples', 'support', 'communication']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('bossy-brain-comic-panels', 'Bossy Brain Comic Panels', 'kids'::resource_kind, 'A cartoon strip where a child draws the bossy brain and what they do instead of obeying it.', 'Use it to help a child name the bossy thoughts and picture a different choice.', array['Children']::text[], '30 minutes', 'The child draws the bossy brain as a character and speech bubbles for what it says. In later panels they show what they do instead. Tell the parent not to answer the questions, and to cheer for the child''s choice. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw the bossy brain"}, {"id": "f1", "type": "textarea", "label": "What it says to me"}, {"id": "f2", "type": "textarea", "label": "What I did instead"}, {"id": "f3", "type": "textarea", "label": "How I felt after"}, {"id": "f4", "type": "textarea", "label": "How my grown-up can help"}]'::jsonb, array['OCD', 'children', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('maybe-maybe-not-uncertainty-game-game', 'Maybe, Maybe Not Uncertainty Game', 'game'::resource_kind, 'A group game where players answer "what if" cards with "maybe, maybe not" and keep going.', 'Use it to help a group practice sitting with uncertainty without needing an answer.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Draw a what-if card and the player says "maybe, maybe not" and then does a small task such as drawing a shape. Others may not reassure. Take turns. Debrief on how it felt not to settle the question and what helped.', '[{"id": "f0", "type": "textarea", "label": "A what-if I drew"}, {"id": "f1", "type": "textarea", "label": "How it felt to leave it unanswered"}, {"id": "f2", "type": "textarea", "label": "What I did while the feeling was there"}, {"id": "f3", "type": "textarea", "label": "A what-if I want to practice with"}]'::jsonb, array['OCD', 'game', 'exposure', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('panic-rise-and-fall-timeline-page', 'Panic Rise and Fall Timeline Page', 'worksheet'::resource_kind, 'A timeline where a client plots how intensity rose, peaked and fell during a recent wave of panic.', 'Use it to help a client see that panic sensations rise and pass.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for a recent episode and plot intensity every minute or so. Seeing the peak and fall in their own handwriting often gives more than being told. Note what the client did at each point. Do not rush through it if it stirs up fear; breathe together.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what I was doing"}, {"id": "f1", "type": "textarea", "label": "How intense it got at the peak (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "About how long it took to peak and ease"}, {"id": "f3", "type": "textarea", "label": "What I did that helped"}, {"id": "f4", "type": "textarea", "label": "What I notice about the shape of it"}]'::jsonb, array['panic attacks', 'panic', 'self-monitoring', 'body awareness']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('body-sensation-meaning-rewrite', 'Body Sensation Meaning Rewrite', 'cbt'::resource_kind, 'A sheet pairing a feared meaning of a body sensation with other explanations.', 'Use it to help a client look at other explanations for body sensations that feel alarming.', array['Adults', 'Teens']::text[], '25 minutes', 'Pick a sensation, such as a racing heart, and the feared meaning. List other explanations, such as effort or a rush of adrenaline. Ask the client to rate belief before and after. A medical check for the sensations is the client''s call and their doctor''s.', '[{"id": "f0", "type": "textarea", "label": "The sensation"}, {"id": "f1", "type": "textarea", "label": "What I fear it means"}, {"id": "f2", "type": "textarea", "label": "Other things it could mean"}, {"id": "f3", "type": "textarea", "label": "How much I believe the fear now (0 to 100)"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself next time"}]'::jsonb, array['panic attacks', 'core CBT', 'panic', 'thinking traps']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('panic-passengers-and-anchors-page', 'Panic Passengers and Anchors Page', 'act'::resource_kind, 'A page for carrying panic feelings along while anchoring in the present and moving toward a value.', 'Use it to help a client let panic sensations be there while they keep doing what matters.', array['Adults']::text[], '25 minutes', 'Pair noticing sensations with an anchor, like feet pressing the floor. The client names what they care about doing even if the feeling shows up. Practice short sessions in office. The goal is not to stop panic; it is to keep living.', '[{"id": "f0", "type": "textarea", "label": "Sensations I noticed"}, {"id": "f1", "type": "textarea", "label": "My anchor in the present"}, {"id": "f2", "type": "textarea", "label": "Something I care about doing"}, {"id": "f3", "type": "textarea", "label": "How I carried the feeling while doing it"}, {"id": "f4", "type": "textarea", "label": "What I would try next time"}]'::jsonb, array['panic attacks', 'core ACT', 'panic', 'mindfulness']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-muscle-release-card', 'Paced Breathing and Muscle Release Card', 'dbt'::resource_kind, 'A card with a slow breathing pace and a muscle-release step for coming down from activation.', 'Use it to give a client a body-based practice for coming down from a wave of activation.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach breathing out longer than in, then tense and release a muscle group. Practice for five minutes when calm so it is familiar. The client logs when they used it and how it went. Not every step works every time; ask what helped.', '[{"id": "f0", "type": "textarea", "label": "When I practiced"}, {"id": "f1", "type": "textarea", "label": "Which step helped most"}, {"id": "f2", "type": "textarea", "label": "My feeling before and after (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "What I want to try next time"}]'::jsonb, array['panic attacks', 'core DBT', 'distress tolerance', 'panic']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('partner-coaching-script-for-a-panic-wave', 'Partner Coaching Script for a Panic Wave', 'couples'::resource_kind, 'A script partners write together for what the partner says and does when a wave of panic starts.', 'Use it to help partners agree on a calm, steady way to help during a wave.', array['Couples']::text[], '30 minutes', 'The client says what helps in the moment, such as a slow voice or staying close. The partner writes what they will say. Practice a brief run-through. Agree on what the partner does not do, such as urging them to calm down.', '[{"id": "f0", "type": "textarea", "label": "Client: what helps when it starts"}, {"id": "f1", "type": "textarea", "label": "Client: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner: what I will say"}, {"id": "f3", "type": "textarea", "label": "Partner: what I will do"}, {"id": "f4", "type": "textarea", "label": "How we will talk about it afterward"}]'::jsonb, array['panic attacks', 'couples', 'support', 'panic']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('family-feelings-check-in-chart-craft', 'Family Feelings Check-In Chart Craft', 'kids'::resource_kind, 'A chart the whole family decorates and uses to show how each person feels at dinner.', 'Use it to help a family make a habit of sharing feelings in small ways.', array['Children', 'Adults']::text[], '30 minutes', 'The child decorates a chart with each person''s name and clip or magnets for feelings. The parent models using it first and responds with "thanks for telling me". Keep it voluntary. Tell the parent to respond with curiosity and not fixes.', '[{"id": "f0", "type": "textarea", "label": "How I feel today"}, {"id": "f1", "type": "textarea", "label": "How I can tell my feeling"}, {"id": "f2", "type": "textarea", "label": "Something that helps when I feel that"}, {"id": "f3", "type": "textarea", "label": "What my grown-up can say when I share"}, {"id": "f4", "type": "textarea", "label": "Where we will keep our chart"}]'::jsonb, array['parenting', 'children', 'emotion identification', 'family']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('praise-practice-game-for-parents', 'Praise Practice Game for Parents', 'game'::resource_kind, 'A group game where parents take turns turning general praise into specific, effort-based praise.', 'Use it to help parents practice praise that names what the child did.', array['Adults', 'Groups']::text[], '25 minutes', 'Read a scenario and each parent offers a praise line. The group suggests how to make it specific, for example "you kept going on that puzzle". Rules: no sarcasm and no "but". Debrief on what is hardest to say.', '[{"id": "f0", "type": "textarea", "label": "A praise line I gave"}, {"id": "f1", "type": "textarea", "label": "How I made it more specific"}, {"id": "f2", "type": "textarea", "label": "What my child might hear in it"}, {"id": "f3", "type": "textarea", "label": "A moment I will praise this week"}]'::jsonb, array['parenting', 'game', 'group', 'skills']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('routine-builder-for-busy-evenings', 'Routine Builder for Busy Evenings', 'worksheet'::resource_kind, 'A worksheet where a parent maps an evening and chooses one change that makes it smoother.', 'Use it to help a parent plan an evening routine with fewer pressure points.', array['Adults']::text[], '30 minutes', 'Map the evening in half-hour blocks and mark the stressful ones. Together, choose one change, such as laying out clothes earlier. Involve the child where possible. Review after a week and adjust without self-blame.', '[{"id": "f0", "type": "textarea", "label": "What my evening looks like now"}, {"id": "f1", "type": "textarea", "label": "The hardest part"}, {"id": "f2", "type": "textarea", "label": "One change I will try"}, {"id": "f3", "type": "textarea", "label": "How my child can help"}, {"id": "f4", "type": "textarea", "label": "What I will check next week"}]'::jsonb, array['parenting', 'routines', 'planning', 'family']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('parent-thought-check-page', 'Parent Thought Check Page', 'cbt'::resource_kind, 'A page where a parent catches a harsh thought about themselves or their child and writes a fairer one.', 'Use it to help a parent notice thoughts that raise stress and try fairer ones.', array['Adults']::text[], '25 minutes', 'Ask for a recent hard moment and the thought that went with it, such as "I am failing". Explore what else is true. The parent writes a fairer thought and notes how stress changes. Hold space for how hard parenting is.', '[{"id": "f0", "type": "textarea", "label": "The hard moment"}, {"id": "f1", "type": "textarea", "label": "The thought that came"}, {"id": "f2", "type": "textarea", "label": "What else is true"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "How my stress changed"}]'::jsonb, array['parenting', 'core CBT', 'self-compassion']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('values-based-parenting-page', 'Values-Based Parenting Page', 'act'::resource_kind, 'A page where a parent names the kind of parent they want to be and a small action that fits.', 'Use it to help a parent pick actions that match the parent they want to be.', array['Adults']::text[], '25 minutes', 'Ask what the parent hopes their child will remember about them. Turn it into values and then into one small action this week. Be gentle about guilt; a value is a direction, not a grade.', '[{"id": "f0", "type": "textarea", "label": "What I hope my child remembers about me"}, {"id": "f1", "type": "textarea", "label": "The values behind that"}, {"id": "f2", "type": "textarea", "label": "A moment this week where I can act on one"}, {"id": "f3", "type": "textarea", "label": "What might get in the way"}, {"id": "f4", "type": "textarea", "label": "What I will do when it does"}]'::jsonb, array['parenting', 'core ACT', 'values']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('please-skills-rest-and-care-plan', 'PLEASE Skills Rest and Care Plan', 'dbt'::resource_kind, 'A plan using the PLEASE letters adapted for sleep, food, movement and care with a new baby.', 'Use it to help a new parent plan small steps for caring for themselves.', array['Adults']::text[], '25 minutes', 'Go through each letter and ask what small step is realistic this week, such as a ten-minute nap swap. Include who can help. Avoid perfect plans, and respect the family''s own circumstances and medical guidance.', '[{"id": "f0", "type": "textarea", "label": "One thing I can do to rest"}, {"id": "f1", "type": "textarea", "label": "One thing I can do to care for my body"}, {"id": "f2", "type": "textarea", "label": "Who can help me this week"}, {"id": "f3", "type": "textarea", "label": "What gets in the way"}, {"id": "f4", "type": "textarea", "label": "What I will try first"}]'::jsonb, array['perinatal and postpartum', 'core DBT', 'self-care', 'support']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('nighttime-duties-and-rest-plan', 'Nighttime Duties and Rest Plan', 'couples'::resource_kind, 'A plan where partners talk about night duties, rest and recovery with a new baby.', 'Use it to help partners share the nights in a way that gives each a stretch of rest.', array['Couples']::text[], '30 minutes', 'Each partner says what they need and what they can give. Map blocks of sleep for each one and agree on handoffs. Check in about resentment gently. Revisit when the baby''s patterns change.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I need and what I can give"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need and what I can give"}, {"id": "f2", "type": "textarea", "label": "Our sleep blocks"}, {"id": "f3", "type": "textarea", "label": "How we hand off"}, {"id": "f4", "type": "textarea", "label": "When we will adjust"}]'::jsonb, array['perinatal and postpartum', 'couples', 'planning', 'support']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('big-sibling-feelings-and-jobs-book', 'Big Sibling Feelings and Jobs Book', 'kids'::resource_kind, 'A craft where an older child makes a book of their feelings and jobs as a big sibling.', 'Use it to help an older child process a new baby and find a role.', array['Children']::text[], '30 minutes', 'The child draws pages such as "what I feel", "what I miss" and "what I can do for the baby". Tell the parent to schedule a little one-to-one time and to read the book together. Follow your reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "How I feel about the baby"}, {"id": "f1", "type": "textarea", "label": "Something I miss"}, {"id": "f2", "type": "textarea", "label": "Something I can help with"}, {"id": "f3", "type": "textarea", "label": "Something I want to do with my grown-up"}, {"id": "f4", "type": "textarea", "label": "Draw our family"}]'::jsonb, array['perinatal and postpartum', 'children', 'family', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('support-circle-role-play-game', 'Support Circle Role Play Game', 'game'::resource_kind, 'A group game where new parents rehearse asking for and receiving help.', 'Use it to help new parents practice asking for specific help.', array['Adults', 'Groups']::text[], '25 minutes', 'Players draw a helper card, such as friend or relative, and practice asking for one specific thing. The helper replies. Turns rotate. Debrief on what made asking easier and what felt hard.', '[{"id": "f0", "type": "textarea", "label": "A request I practiced"}, {"id": "f1", "type": "textarea", "label": "How it felt to ask"}, {"id": "f2", "type": "textarea", "label": "Who I could really ask"}, {"id": "f3", "type": "textarea", "label": "When I will ask"}]'::jsonb, array['perinatal and postpartum', 'game', 'support', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('good-enough-day-page', 'Good Enough Day Page', 'worksheet'::resource_kind, 'A page where a new parent lists what a good-enough day looks like and notes small wins.', 'Use it to help a new parent loosen perfect standards and notice small wins.', array['Adults']::text[], '20 minutes', 'Ask the parent to list what has to happen for a day to be good enough. Cut the list down together. At the end of each day they note small wins. If sadness or worry feels heavy or lasts, encourage contact with their care team; 988 can be reached by call or text at any time.', '[{"id": "f0", "type": "textarea", "label": "What a good-enough day looks like for me"}, {"id": "f1", "type": "textarea", "label": "What I can let go of"}, {"id": "f2", "type": "textarea", "label": "A small win today"}, {"id": "f3", "type": "textarea", "label": "Who I can lean on"}, {"id": "f4", "type": "textarea", "label": "If I need more support I will contact..."}]'::jsonb, array['perinatal and postpartum', 'self-compassion', 'routines', 'support']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('inner-critic-courtroom-sheet', 'Inner Critic Courtroom Sheet', 'cbt'::resource_kind, 'A sheet where the inner critic is put on trial and a fair judge weighs the evidence.', 'Use it to help a client weigh the critic''s claims against the facts.', array['Adults', 'Teens']::text[], '25 minutes', 'The client writes the critic''s charge, the evidence for and against, and a fair verdict. Role-playing the judge sometimes helps. Ask how they feel about the verdict. Repeat with new charges across sessions.', '[{"id": "f0", "type": "textarea", "label": "The critic''s charge"}, {"id": "f1", "type": "textarea", "label": "Evidence for it"}, {"id": "f2", "type": "textarea", "label": "Evidence against it"}, {"id": "f3", "type": "textarea", "label": "The fair judge''s verdict"}, {"id": "f4", "type": "textarea", "label": "How I feel reading the verdict"}]'::jsonb, array['self-esteem', 'core CBT', 'self-criticism', 'self-talk']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('self-worth-is-not-a-scoreboard-page', 'Self-Worth Is Not a Scoreboard Page', 'act'::resource_kind, 'A page contrasting living by values with chasing approval.', 'Use it to help a client shift from chasing approval toward acting on values.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask where the client is chasing approval and what it costs. Then ask what value they could act on instead. Pick one small action. Notice what happens to the feeling of worth.', '[{"id": "f0", "type": "textarea", "label": "Where I chase approval"}, {"id": "f1", "type": "textarea", "label": "What it costs me"}, {"id": "f2", "type": "textarea", "label": "A value I could act on instead"}, {"id": "f3", "type": "textarea", "label": "One small action"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['self-esteem', 'core ACT', 'values', 'self-compassion']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('validate-yourself-statement-card', 'Validate Yourself Statement Card', 'dbt'::resource_kind, 'A card for writing a validating statement about your own experience.', 'Use it to help a client practice validating their own feelings.', array['Adults', 'Teens']::text[], '20 minutes', 'Teach validation: finding what makes sense about a feeling. The client writes a statement for a recent difficult moment, such as "it makes sense I felt hurt because...". Read it aloud. Practice again in session.', '[{"id": "f0", "type": "textarea", "label": "A recent hard moment"}, {"id": "f1", "type": "textarea", "label": "The feeling I had"}, {"id": "f2", "type": "textarea", "label": "It makes sense I felt this way because..."}, {"id": "f3", "type": "textarea", "label": "How it felt to say that"}, {"id": "f4", "type": "textarea", "label": "When I will use it"}]'::jsonb, array['self-esteem', 'core DBT', 'self-validation', 'self-compassion']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('appreciation-exchange-page', 'Appreciation Exchange Page', 'couples'::resource_kind, 'A page where partners write what they value about themselves and about each other.', 'Use it to help partners lift each other''s sense of worth with specific appreciation.', array['Couples']::text[], '25 minutes', 'Each partner writes one thing they value in themselves and two in the other. Read aloud and receive it with a thank-you. Notice what is hard to hear. Repeat weekly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something I value in myself"}, {"id": "f1", "type": "textarea", "label": "Partner A: two things I value in my partner"}, {"id": "f2", "type": "textarea", "label": "Partner B: something I value in myself"}, {"id": "f3", "type": "textarea", "label": "Partner B: two things I value in my partner"}, {"id": "f4", "type": "textarea", "label": "What was hard to hear"}]'::jsonb, array['self-esteem', 'couples', 'connection', 'strengths']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('all-about-me-badge-craft', 'All About Me Badge Craft', 'kids'::resource_kind, 'A craft where a child designs a badge showing the things they are good at and like.', 'Use it to help a child see what they like and do well.', array['Children']::text[], '25 minutes', 'Provide a badge shape and markers. The child fills sections with strengths and favorites. The parent adds one thing they love about the child. Display the badge. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "What I am good at"}, {"id": "f1", "type": "textarea", "label": "What I like"}, {"id": "f2", "type": "textarea", "label": "What a friend would say about me"}, {"id": "f3", "type": "textarea", "label": "What my grown-up loves about me"}, {"id": "f4", "type": "textarea", "label": "Draw my badge"}]'::jsonb, array['self-esteem', 'children', 'strengths', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('small-talk-starters-card-game', 'Small Talk Starters Card Game', 'game'::resource_kind, 'A group game with cards of easy conversation openers that players try in turns.', 'Use it to help a group practice low-stakes conversation openers.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Players draw an opener, ask it of a neighbor and respond. Rules: one follow-up question and no pressure to be interesting. Rate how it felt before and after. Debrief on what predictions came true.', '[{"id": "f0", "type": "textarea", "label": "An opener I tried"}, {"id": "f1", "type": "textarea", "label": "What I predicted would happen"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "An opener I will use this week"}]'::jsonb, array['social anxiety', 'game', 'social skills', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('social-situations-ladder-page', 'Social Situations Ladder Page', 'worksheet'::resource_kind, 'A ladder of social situations from easiest to hardest for a client to approach step by step.', 'Use it to help a client plan a gradual approach to social situations they avoid.', array['Adults', 'Teens']::text[], '30 minutes', 'List situations and rate difficulty. Place them in order and choose one near the bottom. Plan when and how to try. Review what happened after each step and adjust.', '[{"id": "f0", "type": "textarea", "label": "Situations I avoid"}, {"id": "f1", "type": "textarea", "label": "How hard each feels (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "The first step on my ladder"}, {"id": "f3", "type": "textarea", "label": "When I will try it"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['social anxiety', 'exposure', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('spotlight-effect-check-sheet', 'Spotlight Effect Check Sheet', 'cbt'::resource_kind, 'A sheet for checking how much others actually noticed something the client felt was very visible.', 'Use it to help a client test the belief that everyone is watching.', array['Adults', 'Teens']::text[], 'One week', 'The client predicts how many people will notice a small thing, such as a pause. They try it and check, perhaps asking a friend. Compare prediction with outcome. Repeat with other situations.', '[{"id": "f0", "type": "textarea", "label": "What I think people will notice"}, {"id": "f1", "type": "textarea", "label": "My prediction"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['social anxiety', 'core CBT', 'behavioral experiment', 'thinking traps']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('attention-outward-practice-page', 'Attention Outward Practice Page', 'act'::resource_kind, 'A page for practicing shifting attention from self-monitoring to the conversation and surroundings.', 'Use it to help a client turn their attention outward during social moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Practice in session with a short chat. The client notes what they noticed about the other person and the room. Compare to their usual inward focus. Try again at home.', '[{"id": "f0", "type": "textarea", "label": "What I noticed about the other person"}, {"id": "f1", "type": "textarea", "label": "What I noticed in the room"}, {"id": "f2", "type": "textarea", "label": "How often I drifted inward"}, {"id": "f3", "type": "textarea", "label": "How I came back"}, {"id": "f4", "type": "textarea", "label": "What I will try next time"}]'::jsonb, array['social anxiety', 'core ACT', 'mindfulness']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('give-skills-conversation-practice-card', 'GIVE Skills Conversation Practice Card', 'dbt'::resource_kind, 'A card using GIVE (gentle, interested, validate, easy manner) for a conversation.', 'Use it to help a client practice staying warm and engaged in a conversation.', array['Adults', 'Teens']::text[], '25 minutes', 'Walk through each letter and role-play a short exchange. The client picks one letter to focus on. Review what felt natural. Practice in a low-stakes real conversation.', '[{"id": "f0", "type": "textarea", "label": "A conversation I plan to have"}, {"id": "f1", "type": "textarea", "label": "How I will be gentle"}, {"id": "f2", "type": "textarea", "label": "How I will show interest"}, {"id": "f3", "type": "textarea", "label": "What I will validate"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['social anxiety', 'core DBT', 'interpersonal effectiveness', 'social skills']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('memory-jar-decorating-craft', 'Memory Jar Decorating Craft', 'kids'::resource_kind, 'A craft where a child decorates a jar and fills it with drawings and notes about someone they miss.', 'Use it to help a child keep memories of someone close and have a place for them.', array['Children']::text[], '30 minutes', 'The child decorates the jar and adds slips with a favorite memory, a thing they miss and a thing they want to say. Tell the parent to read it together only if the child invites it. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Who this jar is for"}, {"id": "f1", "type": "textarea", "label": "A favorite memory"}, {"id": "f2", "type": "textarea", "label": "Something I miss"}, {"id": "f3", "type": "textarea", "label": "Something I want to say"}, {"id": "f4", "type": "textarea", "label": "Where we will keep the jar"}]'::jsonb, array['grief and loss', 'children', 'art', 'play']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('remembering-stories-circle', 'Remembering Stories Circle', 'game'::resource_kind, 'A circle game where members take turns sharing a story about someone they lost, with a pass option.', 'Use it to help a group share memories and support each other in grief.', array['Adults', 'Groups']::text[], '40 minutes', 'Pass an object around. The holder shares a short memory or says "pass". Rules: no advice, no comparing losses, and what is said stays in the room. Debrief on what it was like to speak and to listen.', '[{"id": "f0", "type": "textarea", "label": "A memory I shared or held back"}, {"id": "f1", "type": "textarea", "label": "What it was like to listen to others"}, {"id": "f2", "type": "textarea", "label": "A feeling I noticed"}, {"id": "f3", "type": "textarea", "label": "Something that supports me this week"}]'::jsonb, array['grief and loss', 'game', 'group', 'support']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('grief-waves-and-anchors-page', 'Grief Waves and Anchors Page', 'worksheet'::resource_kind, 'A page where a client notes what triggers waves of grief and what anchors them.', 'Use it to help a client notice what brings grief up and what steadies them.', array['Adults', 'Teens']::text[], 'One week', 'The client logs a wave: what happened just before, how strong it was and what they did. List anchors, such as a person to call. Grief is not on a schedule, and there is no right way to move through it.', '[{"id": "f0", "type": "textarea", "label": "What came just before the wave"}, {"id": "f1", "type": "textarea", "label": "How strong it was (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What anchored me"}, {"id": "f4", "type": "textarea", "label": "Who I can lean on"}]'::jsonb, array['grief and loss', 'self-monitoring', 'support', 'coping skills']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('unhelpful-guilt-thoughts-sheet', 'Unhelpful Guilt Thoughts Sheet', 'cbt'::resource_kind, 'A sheet for looking at "if only" thoughts and writing a fairer perspective.', 'Use it to help a client look at guilt thoughts after a loss with more fairness.', array['Adults']::text[], '25 minutes', 'Ask for an "if only" thought and what the client knew at the time. Explore what else was true and what a friend would say. Hold the guilt with compassion; do not rush to dismiss it. Notice how the feeling shifts.', '[{"id": "f0", "type": "textarea", "label": "The \"if only\" thought"}, {"id": "f1", "type": "textarea", "label": "What I knew at the time"}, {"id": "f2", "type": "textarea", "label": "What else is true"}, {"id": "f3", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f4", "type": "textarea", "label": "How I feel now"}]'::jsonb, array['grief and loss', 'core CBT', 'self-blame', 'self-compassion']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('carrying-love-and-loss-together-page', 'Carrying Love and Loss Together Page', 'act'::resource_kind, 'A page that holds sadness and love for the one lost together, with a value-based action.', 'Use it to help a client carry grief while acting on what they still value.', array['Adults']::text[], '25 minutes', 'Ask what the client loves about the one they lost and what the sadness shows about it. Choose a small action that honors that value. Grief and values can live side by side. Let tears be there.', '[{"id": "f0", "type": "textarea", "label": "What I loved about them"}, {"id": "f1", "type": "textarea", "label": "What my sadness shows me"}, {"id": "f2", "type": "textarea", "label": "A value I want to carry forward"}, {"id": "f3", "type": "textarea", "label": "A small action that honors it"}, {"id": "f4", "type": "textarea", "label": "How I will care for myself"}]'::jsonb, array['grief and loss', 'core ACT', 'values', 'acceptance']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('give-and-dear-man-pairing-sheet', 'GIVE and DEAR MAN Pairing Sheet', 'dbt'::resource_kind, 'A sheet for pairing GIVE and DEAR MAN to plan a hard conversation.', 'Use it to help a client plan a request that keeps both the goal and the relationship in view.', array['Adults', 'Teens']::text[], '30 minutes', 'Write the DEAR MAN lines and then add the GIVE touches. Rehearse aloud. Plan for what to do if the other person says no. Review how it went afterward.', '[{"id": "f0", "type": "textarea", "label": "The conversation"}, {"id": "f1", "type": "textarea", "label": "My DEAR MAN lines"}, {"id": "f2", "type": "textarea", "label": "How I will keep it gentle"}, {"id": "f3", "type": "textarea", "label": "What I will do if the answer is no"}, {"id": "f4", "type": "textarea", "label": "How it went"}]'::jsonb, array['relationship issues', 'core DBT', 'interpersonal effectiveness', 'DEAR MAN']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('small-bids-and-responses-log', 'Small Bids and Responses Log', 'couples'::resource_kind, 'A log where partners note small bids for attention and how they responded.', 'Use it to help partners notice small bids and turn toward them.', array['Couples']::text[], 'One week', 'Explain bids as small invitations such as a comment or a sigh. Each partner logs bids they made and noticed. Review responses: turned toward, away or against. Choose one to do more of.', '[{"id": "f0", "type": "textarea", "label": "Partner A: bids I made and noticed"}, {"id": "f1", "type": "textarea", "label": "Partner B: bids I made and noticed"}, {"id": "f2", "type": "textarea", "label": "How we responded"}, {"id": "f3", "type": "textarea", "label": "One bid we will turn toward more"}, {"id": "f4", "type": "textarea", "label": "What we noticed"}]'::jsonb, array['relationship issues', 'couples', 'Gottman', 'connection']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('feelings-in-my-family-houses-drawing', 'Feelings in My Family Houses Drawing', 'kids'::resource_kind, 'A drawing where a child draws a house for each family member and what feels like inside.', 'Use it to help a child show how they see family relationships.', array['Children']::text[], '30 minutes', 'The child draws houses and fills them with colors and people. Ask neutral questions. Tell the parent to receive the drawing without correcting it. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your family houses"}, {"id": "f1", "type": "textarea", "label": "Which house feels warm"}, {"id": "f2", "type": "textarea", "label": "Which house feels hard"}, {"id": "f3", "type": "textarea", "label": "What I wish for in my family"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to"}]'::jsonb, array['relationship issues', 'children', 'family', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('say-it-kindly-role-play-game', 'Say It Kindly Role Play Game', 'game'::resource_kind, 'A game of turning a blunt remark into a kind and clear one.', 'Use it to help a group practice kind, clear speech in relationships.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Read a blunt line and the player rewrites it. The group votes whether it is kind and clear. Turns rotate. Debrief on what was hardest and on lines they use.', '[{"id": "f0", "type": "textarea", "label": "A blunt line I heard or said"}, {"id": "f1", "type": "textarea", "label": "My kinder version"}, {"id": "f2", "type": "textarea", "label": "Whether it stayed clear"}, {"id": "f3", "type": "textarea", "label": "One line I will use this week"}]'::jsonb, array['relationship issues', 'game', 'communication', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('relationship-needs-and-boundaries-page', 'Relationship Needs and Boundaries Page', 'worksheet'::resource_kind, 'A page listing what a client needs from relationships and where they want boundaries.', 'Use it to help a client name needs and boundaries in a relationship.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for needs and for places where the client feels stretched. Turn each boundary into a sentence they might say. Role-play one. Revisit after trying.', '[{"id": "f0", "type": "textarea", "label": "What I need from my relationships"}, {"id": "f1", "type": "textarea", "label": "Where I feel stretched"}, {"id": "f2", "type": "textarea", "label": "A boundary I want"}, {"id": "f3", "type": "textarea", "label": "How I will say it"}, {"id": "f4", "type": "textarea", "label": "What I will do if it is not respected"}]'::jsonb, array['relationship issues', 'boundaries', 'communication', 'planning']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('blame-belongs-where-it-belongs-sheet', 'Blame Belongs Where It Belongs Sheet', 'cbt'::resource_kind, 'A sheet for looking at self-blame thoughts in the present and writing a fairer one.', 'Use it to help a client notice self-blame thoughts and move toward a fairer view.', array['Adults', 'Teens']::text[], '25 minutes', 'Work with the current thought, such as "it was my fault", and not with details of what happened. Ask what a friend would say and where responsibility lies. Pace carefully and stop to ground if needed. Never ask for a written account.', '[{"id": "f0", "type": "textarea", "label": "A self-blame thought I have today"}, {"id": "f1", "type": "textarea", "label": "How much I believe it (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend"}, {"id": "f3", "type": "textarea", "label": "A fairer thought"}, {"id": "f4", "type": "textarea", "label": "What helps me feel steady"}]'::jsonb, array['sexual abuse', 'core CBT', 'self-blame', 'safety']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('taking-back-choices-page', 'Taking Back Choices Page', 'act'::resource_kind, 'A page listing small choices a client makes today that are theirs, tied to values.', 'Use it to help a client notice choices and control they have now.', array['Adults', 'Teens']::text[], '20 minutes', 'Keep it in the present: small daily choices such as what to wear or when to rest. Link each to a value. Do not ask about the past. Celebrate choices without pressure.', '[{"id": "f0", "type": "textarea", "label": "A choice I made today"}, {"id": "f1", "type": "textarea", "label": "The value it came from"}, {"id": "f2", "type": "textarea", "label": "A choice I want to make this week"}, {"id": "f3", "type": "textarea", "label": "What supports me in it"}, {"id": "f4", "type": "textarea", "label": "How it feels to choose"}]'::jsonb, array['sexual abuse', 'core ACT', 'values', 'safety']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('grounding-with-the-five-senses-card', 'Grounding With the Five Senses Card', 'dbt'::resource_kind, 'A card for naming things the client can see, hear, touch, smell and taste right now.', 'Use it to help a client come back to the present when feelings surge.', array['Adults', 'Teens']::text[], '15 minutes', 'Teach the five senses step in session and practice when calm. The client writes what they notice in each. Keep eyes open if closing them feels unsafe. Use it any time the client wants.', '[{"id": "f0", "type": "textarea", "label": "Five things I can see"}, {"id": "f1", "type": "textarea", "label": "Four things I can touch"}, {"id": "f2", "type": "textarea", "label": "Three things I can hear"}, {"id": "f3", "type": "textarea", "label": "Two things I can smell"}, {"id": "f4", "type": "textarea", "label": "One thing I can taste"}]'::jsonb, array['sexual abuse', 'core DBT', 'grounding', 'safety']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('safety-and-pacing-agreement-for-partners', 'Safety and Pacing Agreement for Partners', 'couples'::resource_kind, 'An agreement where partners decide how to respect a survivor''s pace and boundaries.', 'Use it to help partners build trust through pacing, choice and clear signals.', array['Couples']::text[], '30 minutes', 'The partner who is a survivor decides what they want to share and when. Both agree on stop signals and boundaries in closeness. Nothing about past details is required. Revisit often.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps me feel safe"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I can support that"}, {"id": "f2", "type": "textarea", "label": "Our stop signal"}, {"id": "f3", "type": "textarea", "label": "What closeness looks like right now"}, {"id": "f4", "type": "textarea", "label": "When we will check in"}]'::jsonb, array['sexual abuse', 'couples', 'safety', 'pacing']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('my-safe-people-hand-craft', 'My Safe People Hand Craft', 'kids'::resource_kind, 'A craft where a child traces a hand and writes a trusted grown-up on each finger.', 'Use it to help a child name trusted grown-ups they can tell.', array['Children']::text[], '25 minutes', 'The child traces a hand and writes or draws a safe person on each finger. Practice who to tell and how. Remind yourself of your reporting duties if a child discloses. Tell the parent to keep the hand where the child can see it.', '[{"id": "f0", "type": "textarea", "label": "Draw your hand and write a safe person on each finger"}, {"id": "f1", "type": "textarea", "label": "How I can tell them something hard"}, {"id": "f2", "type": "textarea", "label": "What they will do"}, {"id": "f3", "type": "textarea", "label": "Who is at school"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my hand"}]'::jsonb, array['sexual abuse', 'children', 'safety', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('coping-skills-charades', 'Coping Skills Charades', 'game'::resource_kind, 'A charades game where players act out coping skills for the group to guess.', 'Use it to help a group learn and recall a wide range of coping skills.', array['Children', 'Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Write skills on cards, such as stretching or listening to music. Players act without words while the group guesses. Turns rotate. Debrief on which skills they will try.', '[{"id": "f0", "type": "textarea", "label": "A skill I acted or guessed"}, {"id": "f1", "type": "textarea", "label": "One I had not thought of"}, {"id": "f2", "type": "textarea", "label": "One I will try"}, {"id": "f3", "type": "textarea", "label": "When I might use it"}]'::jsonb, array['coping skills', 'game', 'group', 'skills']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('coping-skills-menu-by-mood', 'Coping Skills Menu by Mood', 'worksheet'::resource_kind, 'A menu that groups coping skills by the mood they fit, with space to add favorites.', 'Use it to help a client pick a skill that suits the way they feel.', array['Adults', 'Teens']::text[], '20 minutes', 'Divide a page by moods, such as restless or heavy, and fill in skills for each. Mark ones that have worked. Keep a photo on a phone. Add to it each week.', '[{"id": "f0", "type": "textarea", "label": "Skills for when I feel restless"}, {"id": "f1", "type": "textarea", "label": "Skills for when I feel heavy"}, {"id": "f2", "type": "textarea", "label": "Skills for when I feel anxious"}, {"id": "f3", "type": "textarea", "label": "My favorite skill"}, {"id": "f4", "type": "textarea", "label": "One I will try this week"}]'::jsonb, array['coping skills', 'planning', 'regulation', 'routines']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('pocket-coping-statement-cards', 'Pocket Coping Statement Cards', 'cbt'::resource_kind, 'A set of index cards with coping statements the client writes in their own words.', 'Use it to help a client carry short, believable coping thoughts into hard moments.', array['Adults', 'Teens']::text[], '20 minutes', 'Ask for situations that are tough and a statement that feels believable, not forced. Write it on a card. Practice reading it. Revise any that sound hollow.', '[{"id": "f0", "type": "textarea", "label": "A tough situation"}, {"id": "f1", "type": "textarea", "label": "A believable coping thought"}, {"id": "f2", "type": "textarea", "label": "Another thought for the same situation"}, {"id": "f3", "type": "textarea", "label": "Where I will keep my cards"}, {"id": "f4", "type": "textarea", "label": "When I used one"}]'::jsonb, array['coping skills', 'core CBT', 'self-talk']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('expanding-my-coping-toolbox-page', 'Expanding My Coping Toolbox Page', 'act'::resource_kind, 'A page for judging coping skills by whether they move a client toward what matters.', 'Use it to help a client choose coping skills that fit their values.', array['Adults', 'Teens']::text[], '25 minutes', 'List what the client does when upset. Ask which take them toward their values over time. Add one new skill that fits. Practice it in session.', '[{"id": "f0", "type": "textarea", "label": "What I do when upset"}, {"id": "f1", "type": "textarea", "label": "Which ones help over time"}, {"id": "f2", "type": "textarea", "label": "Which ones cost me"}, {"id": "f3", "type": "textarea", "label": "A new skill to try"}, {"id": "f4", "type": "textarea", "label": "The value it serves"}]'::jsonb, array['coping skills', 'core ACT', 'workability', 'values']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('self-soothe-with-the-senses-plan', 'Self-Soothe With the Senses Plan', 'dbt'::resource_kind, 'A plan with a soothing item for each sense that a client can reach quickly.', 'Use it to help a client soothe themselves through the senses.', array['Adults', 'Teens']::text[], '20 minutes', 'For each sense, the client names a soothing item, such as a scent. Build a small kit. Practice one in session. Review what worked.', '[{"id": "f0", "type": "textarea", "label": "Something soothing to see"}, {"id": "f1", "type": "textarea", "label": "Something soothing to hear"}, {"id": "f2", "type": "textarea", "label": "Something soothing to smell"}, {"id": "f3", "type": "textarea", "label": "Something soothing to touch"}, {"id": "f4", "type": "textarea", "label": "Where my kit lives"}]'::jsonb, array['coping skills', 'core DBT', 'self-soothing', 'distress tolerance']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('supporter-role-plan-for-facing-a-fear', 'Supporter Role Plan for Facing a Fear', 'couples'::resource_kind, 'A plan where a partner learns how to support a step toward a feared thing without pushing.', 'Use it to help a partner support exposure steps in a calm way.', array['Couples']::text[], '30 minutes', 'The client describes their ladder and what help feels good. The partner says what they can do and not do, such as not rushing. Plan one step with both roles. Review how it felt for each.', '[{"id": "f0", "type": "textarea", "label": "Client: my next step"}, {"id": "f1", "type": "textarea", "label": "Client: what helps and what does not"}, {"id": "f2", "type": "textarea", "label": "Partner: what I will do"}, {"id": "f3", "type": "textarea", "label": "Partner: what I will not do"}, {"id": "f4", "type": "textarea", "label": "How we will talk about it after"}]'::jsonb, array['phobias', 'couples', 'exposure', 'support']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('fear-ladder-picture-book', 'Fear Ladder Picture Book', 'kids'::resource_kind, 'A picture book where a child draws each step of a ladder toward a feared thing.', 'Use it to help a child see a feared thing as a series of small steps.', array['Children']::text[], '30 minutes', 'The child draws each step from easiest to hardest and decorates the cover. Tell the parent to cheer each step and never to push or trick. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "The thing I am afraid of"}, {"id": "f1", "type": "textarea", "label": "My smallest step"}, {"id": "f2", "type": "textarea", "label": "The next steps"}, {"id": "f3", "type": "textarea", "label": "What helps me feel brave"}, {"id": "f4", "type": "textarea", "label": "How my grown-up can help"}]'::jsonb, array['phobias', 'children', 'exposure', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('fear-facing-dice-game', 'Fear Facing Dice Game', 'game'::resource_kind, 'A game where a roll picks a small exposure step for the group to cheer.', 'Use it to make small exposure steps playful and shared in a group.', array['Children', 'Teens', 'Groups']::text[], '30 minutes', 'Make a list of steps for each number. A player rolls and chooses one step to try now or plan. The group cheers effort. Turns rotate. Debrief on what predictions came true.', '[{"id": "f0", "type": "textarea", "label": "The step I rolled"}, {"id": "f1", "type": "textarea", "label": "What I predicted"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "The step I will do this week"}]'::jsonb, array['phobias', 'game', 'exposure', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('fear-thermometer-log', 'Fear Thermometer Log', 'worksheet'::resource_kind, 'A log where a client rates fear before, during and after a step toward a feared thing.', 'Use it to help a client see how fear changes while they stay with a step.', array['Adults', 'Teens']::text[], 'One week', 'The client rates fear at start, middle and end of each practice. Review the pattern together. Note what helped them stay. Raise the difficulty only when ready.', '[{"id": "f0", "type": "textarea", "label": "The step I practiced"}, {"id": "f1", "type": "textarea", "label": "Fear at the start (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "Fear in the middle"}, {"id": "f3", "type": "textarea", "label": "Fear at the end"}, {"id": "f4", "type": "textarea", "label": "What helped me stay"}]'::jsonb, array['phobias', 'exposure', 'self-monitoring', 'avoidance']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('feared-outcome-versus-actual-sheet', 'Feared Outcome Versus Actual Sheet', 'cbt'::resource_kind, 'A sheet that asks the client what they expect and what happened when they approached a feared thing.', 'Use it to help a client compare what they predicted with what happened.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask for the feared outcome and how likely it feels. After an approach, record what happened. Compare without judgment. Plan the next step.', '[{"id": "f0", "type": "textarea", "label": "The outcome I fear"}, {"id": "f1", "type": "textarea", "label": "How likely it feels (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What happened when I approached"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "My next step"}]'::jsonb, array['phobias', 'core CBT', 'exposure', 'behavioral experiment']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('body-as-a-place-i-live-page', 'Body as a Place I Live Page', 'act'::resource_kind, 'A page for noticing what the body does and carries the client through, with values attached.', 'Use it to help a client relate to their body by what it lets them do.', array['Adults', 'Teens']::text[], '25 minutes', 'Ask what the body helps the client do, such as hug, walk or laugh. Link each to a value. When critical thoughts show up, practice noticing them as thoughts. Keep the focus on function and care.', '[{"id": "f0", "type": "textarea", "label": "Things my body lets me do"}, {"id": "f1", "type": "textarea", "label": "A value each one serves"}, {"id": "f2", "type": "textarea", "label": "A critical thought that shows up"}, {"id": "f3", "type": "textarea", "label": "What I do when it does"}, {"id": "f4", "type": "textarea", "label": "A kind act I can do for my body"}]'::jsonb, array['body image', 'core ACT', 'self-compassion', 'values']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('wear-what-feels-good-opposite-action-page', 'Wear What Feels Good Opposite Action Page', 'dbt'::resource_kind, 'A page for acting opposite to the urge to hide and wearing something comfortable.', 'Use it to help a client act opposite to the urge to hide.', array['Adults', 'Teens']::text[], '20 minutes', 'Name the urge to hide or cover up. Plan an opposite step, such as wearing something comfy and going out. Rate feelings before and after. Review what happened.', '[{"id": "f0", "type": "textarea", "label": "The urge I noticed"}, {"id": "f1", "type": "textarea", "label": "The opposite step I planned"}, {"id": "f2", "type": "textarea", "label": "How I felt before (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "How I felt after (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "What I learned"}]'::jsonb, array['body image', 'core DBT', 'opposite action', 'emotion regulation']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('kind-words-about-each-others-bodies-page', 'Kind Words About Each Other''s Bodies Page', 'couples'::resource_kind, 'A page where partners practice kind words about each other and themselves.', 'Use it to help partners speak with care about themselves and each other.', array['Couples']::text[], '25 minutes', 'Each partner names something they appreciate about what their own body does and something about the other. Avoid comparisons. Notice what is hard to hear. Repeat weekly.', '[{"id": "f0", "type": "textarea", "label": "Partner A: something my body does that I appreciate"}, {"id": "f1", "type": "textarea", "label": "Partner B: something my body does that I appreciate"}, {"id": "f2", "type": "textarea", "label": "What I appreciate about my partner"}, {"id": "f3", "type": "textarea", "label": "What was hard to hear"}, {"id": "f4", "type": "textarea", "label": "What we will try this week"}]'::jsonb, array['body image', 'couples', 'connection', 'self-compassion']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('my-amazing-body-superhero-drawing', 'My Amazing Body Superhero Drawing', 'kids'::resource_kind, 'A drawing where a child makes a superhero showing what their body can do.', 'Use it to help a child celebrate what their body can do.', array['Children']::text[], '25 minutes', 'The child draws a superhero with powers like running or hugging. Ask the child what each power does. Tell the parent to talk about what bodies do and not how they look. Follow reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw your superhero"}, {"id": "f1", "type": "textarea", "label": "What powers my body has"}, {"id": "f2", "type": "textarea", "label": "My favorite thing my body does"}, {"id": "f3", "type": "textarea", "label": "What my body needs from me"}, {"id": "f4", "type": "textarea", "label": "What my grown-up loves about what I do"}]'::jsonb, array['body image', 'children', 'strengths', 'art']::text[], '2026-10-25T15:00:00+00:00'::timestamptz),
  ('kind-mirror-compliment-game', 'Kind Mirror Compliment Game', 'game'::resource_kind, 'A game where players compliment each other on things that are not looks.', 'Use it to help a group notice qualities beyond appearance.', array['Teens', 'Adults', 'Groups']::text[], '25 minutes', 'Pass a hand mirror. The holder hears one kind thing about their actions or character. Rules: no remarks on looks. Debrief on how it felt.', '[{"id": "f0", "type": "textarea", "label": "A thing I heard about myself"}, {"id": "f1", "type": "textarea", "label": "How it felt"}, {"id": "f2", "type": "textarea", "label": "A thing I said to someone else"}, {"id": "f3", "type": "textarea", "label": "A quality I want to notice in myself"}]'::jsonb, array['body image', 'game', 'strengths', 'group']::text[], '2026-10-25T15:00:00+00:00'::timestamptz)
